}

/* =====================================================
   MODAL
   ===================================================== */
.dark .modal-content {
  background-color: var(--sb-surface) !important;
  border: 1px solid var(--sb-border) !important;
  border-radius: var(--sb-radius-lg) !important;
}

.dark .modal-header,
.dark .modal-footer {
