  border-color: var(--sb-green-border) !important;
  color: var(--sb-green) !important;
}

/* =====================================================
   BORDER OVERRIDES
   ===================================================== */
.dark .border-border,
.dark .border {
  border-color: var(--sb-border) !important;
}

.dark .border-b {
  border-bottom-color: var(--sb-border-subtle) !important;
}

.dark .border-t {
  border-top-color: var(--sb-border-subtle) !important;
}

.dark .border-e {
  border-inline-end-color: var(--sb-border-subtle) !important;
}

/* =====================================================
   BACKGROUND OVERRIDES
   ===================================================== */
.dark .bg-background {
  background-color: var(--sb-page) !important;
}

.dark .bg-card {
  background-color: var(--sb-surface) !important;
}

.dark .bg-muted,
.dark .bg-muted\/10,
.dark .bg-muted\/30,
.dark .bg-muted\/50 {
  background-color: rgba(255, 255, 255, 0.04) !important;
}

/* Remove Metronic's upgrade-bg gradient */
.dark .upgrade-bg {
  background-image: none !important;
  background-color: var(--sb-surface) !important;
}

/* =====================================================
   DIVIDERS
   ===================================================== */
.dark .divide-y > *,
.dark hr {
  border-color: var(--sb-border-subtle) !important;
}

/* =====================================================
   PROGRESS
   ===================================================== */
.dark .progress,
.dark .ttsc-progress {
  background-color: rgba(255, 255, 255, 0.06) !important;
  border-radius: 9999px !important;
}

.dark .progress-bar {
  background-color: var(--sb-green) !important;
  border-radius: 9999px !important;
}

/* =====================================================
   ALERTS
   ===================================================== */
.dark .alert {
  border-radius: var(--sb-radius) !important;
  border-width: 1px !important;
}

.dark .alert-primary {
  border-color: var(--sb-green-border) !important;
  color: var(--sb-green) !important;
}

.dark .alert-danger {
  border-color: rgba(239, 68, 68, 0.3) !important;
  color: var(--sb-danger) !important;
}

/* =====================================================
   LOGO (show dark, hide light)
   ===================================================== */
.dark img[src*="default-logo.svg"]:not([src*="dark"]) {
  display: none !important;
}

.dark img[src*="default-logo-dark.svg"] {
  display: block !important;
}

/* =====================================================
   NOTIFICATION / TOAST
   ===================================================== */
.dark .ttsc-notification {
  background-color: var(--sb-surface) !important;
  border: 1px solid var(--sb-border) !important;
  border-radius: var(--sb-radius) !important;
  color: var(--sb-text) !important;
}

/* =====================================================
   SCROLLBAR
   ===================================================== */
.dark ::-webkit-scrollbar-track {
  background: var(--sb-page) !important;
}

.dark ::-webkit-scrollbar-thumb {
  background: var(--sb-border) !important;
  border-radius: 9999px !important;
}

.dark ::-webkit-scrollbar-thumb:hover {
  background: var(--sb-border-prominent) !important;
}

/* =====================================================
   SELECT WRAP (Supabase Pattern)
   ===================================================== */
.select-wrap {
    display: inline-block;
    width: 100%;
    vertical-align: middle;
    position: relative;
}

.select-trigger {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 0.5rem 0.75rem;
    background-color: var(--surface, #ffffff);
    border: 1px solid var(--border, #e2e8f0);
    border-radius: var(--radius-sm, 6px);
    color: var(--fg, #1e293b);
    font-size: 0.8125rem;
    cursor: pointer;
    user-select: none;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    box-sizing: border-box;
    min-height: 38px;
}

.select-trigger:hover {
    border-color: var(--border-strong, #cbd5e1);
}

.select-trigger[aria-expanded="true"] {
    border-color: var(--accent, #3ecf8e);
    box-shadow: var(--focus-ring, 0 0 0 2px rgba(62, 207, 142, 0.15));
}

.select-trigger .value {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.select-trigger .caret {
    flex-shrink: 0;
    color: var(--meta, #94a3b8);
    margin-left: 6px;
    transition: transform 0.2s ease;
}

.select-trigger[aria-expanded="true"] .caret {
    transform: rotate(180deg);
}

.menu {
    display: none;
    position: absolute;
    top: calc(100% + 4px);
    left: 0;
    right: 0;
    background: var(--surface, #ffffff);
    border: 1px solid var(--border, #e2e8f0);
    border-radius: var(--radius-sm, 6px);
    box-shadow: var(--elev-raised, 0 4px 16px rgba(0, 0, 0, 0.1));
    max-height: 240px;
    overflow-y: auto;
    z-index: 9999;
    box-sizing: border-box;
    padding: 4px 0;
    pointer-events: auto;
}

.menu.is-open {
    display: block;
}

.menu .item {
    padding: 0.5rem 0.75rem;
    font-size: 0.8125rem;
    color: var(--fg, #1e293b);
    cursor: pointer;
    transition: background-color 0.12s ease;
    display: flex;
    align-items: center;
}

.menu .item:hover {
    background-color: var(--surface-2, #f1f5f9);
}

.menu .item.is-selected {
    background-color: var(--accent-soft, rgba(62, 207, 142, 0.14));
    color: var(--accent, #3ecf8e);
    font-weight: 500;
}

.dark .select-trigger {
    background-color: var(--sb-surface);
    border-color: var(--sb-border);
    color: var(--sb-text);
}

.dark .select-trigger:hover {
    border-color: var(--sb-border-prominent);
}

.dark .select-trigger[aria-expanded="true"] {
    border-color: var(--sb-green);
    box-shadow: 0 0 0 2px rgba(62, 207, 142, 0.15);
}

.dark .select-trigger .caret {
    color: var(--sb-text-muted);
}

.dark .menu {
    background: var(--sb-surface);
    border-color: var(--sb-border);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
}

.dark .menu .item {
    color: var(--sb-text-secondary);
}

.dark .menu .item:hover {
    background-color: rgba(255, 255, 255, 0.05);
}

.dark .menu .item.is-selected {
    background-color: rgba(62, 207, 142, 0.12);
    color: var(--sb-green);
}

/* =====================================================
   SELECTION
   ===================================================== */
.dark ::selection {
  background-color: rgba(62, 207, 142, 0.2) !important;
  color: var(--sb-text) !important;
}

/* =====================================================
   LIST GROUP
   ===================================================== */
.dark .list-group-item {
  background-color: transparent !important;
  border-color: var(--sb-border-subtle) !important;
  color: var(--sb-text-secondary) !important;
}

/* =====================================================
   PRE / CODE
   ===================================================== */
.dark pre,
.dark code {
  background-color: var(--sb-sidebar-bg) !important;
  color: var(--sb-text-secondary) !important;
  border: 1px solid var(--sb-border-subtle) !important;
  border-radius: 6px !important;
}

/* =====================================================
   SB-* COMPONENT NAMESPACE (for new pages)
   Light-mode defaults + dark-mode overrides below
   ===================================================== */

/* sb-btn \2014  Light mode */
.sb-btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: 8px; font-size: 14px; font-weight: 500;
  font-family: var(--font-display, "Inter"), system-ui, sans-serif;
  padding: 8px 24px; border: 1px solid transparent;
  cursor: pointer; border-radius: var(--radius-sm, 6px);
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
  background: var(--surface, #ffffff); color: var(--fg, #1c1c1c); border-color: var(--border, #e5e7eb);
}
.sb-btn:hover { border-color: var(--border-strong, #d1d5db); }
.sb-btn:focus-visible { outline: none; box-shadow: var(--focus-ring, 0 0 0 2px rgba(62, 207, 142, 0.5)); }
.sb-btn:disabled { opacity: 0.5; cursor: not-allowed; }
.sb-btn-sm { padding: 6px 16px; font-size: 13px; }
.sb-btn-xs { padding: 4px 12px; font-size: 11px; }

/* sb-card \2014  Light mode */
.sb-card {
  background: var(--surface, #ffffff); border: 1px solid var(--border, #e5e7eb);
  border-radius: var(--radius-lg, 12px); padding: 20px;
  transition: border-color 0.15s ease;
}
.sb-card:hover { border-color: var(--border-strong, #d1d5db); }
.sb-card-header {
  display: flex; align-items: center; justify-content: space-between;
  padding-bottom: 16px; border-bottom: 1px solid var(--border-soft, #ebebeb);
  margin-bottom: 16px;
}
.sb-card-title { font-size: 14px; font-weight: 500; color: var(--fg, #1c1c1c); }

/* sb-widget \2014  Light mode */
.sb-widget {
  background: var(--surface, #ffffff); border: 1px solid var(--border, #e5e7eb);
  border-radius: var(--radius-md, 8px); padding: 16px 20px;
  transition: border-color 0.15s ease;
}
.sb-widget:hover { border-color: var(--border-strong, #d1d5db); }
.sb-widget-value { font-size: 28px; font-weight: 400; color: var(--fg, #1c1c1c); line-height: 1.2; }
.sb-widget-label { font-size: 12px; font-weight: 400; color: var(--muted, #6b6b6b); margin-top: 2px; }
.sb-widget-icon { width: 36px; height: 36px; border-radius: var(--radius-sm, 6px); display: flex; align-items: center; justify-content: center; font-size: 16px; flex-shrink: 0; }
.sb-widget-bar { height: 3px; background: color-mix(in oklab, var(--fg, #1c1c1c) 8%, transparent); border-radius: 9999px; overflow: hidden; margin-top: 8px; }
.sb-widget-bar-fill { height: 100%; border-radius: 9999px; transition: width 1s ease; }
.sb-fill-green { background: var(--accent, #3ecf8e); }
.sb-fill-red { background: var(--danger, #ef4444); }
.sb-fill-yellow { background: var(--warn, #f59e0b); }
.sb-fill-cyan { background: var(--info, #06b6d4); }
.sb-fill-purple { background: #a855f7; }

/* sb-table-container \2014  Light mode */
.sb-table-container { background: var(--surface, #ffffff); border: 1px solid var(--border, #e5e7eb); border-radius: var(--radius-lg, 12px); }

/* sb-table \2014  Light mode */
.sb-table { width: 100%; border-collapse: collapse; }
.sb-table th { text-align: left; padding: 10px 16px; font-size: 11px; font-weight: 500; color: var(--muted, #6b6b6b); text-transform: uppercase; letter-spacing: 0.5px; border-bottom: 1px solid var(--border-soft, #ebebeb); }
.sb-table td { padding: 10px 16px; font-size: 13px; color: var(--fg-2, #4d4d4d); border-bottom: 1px solid var(--border-soft, #ebebeb); }
.sb-table tr:hover td { background: var(--surface-2, rgba(0, 0, 0, 0.02)); }
.sb-text-primary { color: var(--fg, #1c1c1c); }

/* sb-badge \2014  Light mode */
.sb-badge { display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 9999px; font-size: 11px; font-weight: 500; text-transform: uppercase; letter-spacing: 0.3px; }
.sb-badge-green { background: var(--accent-soft, rgba(62, 207, 142, 0.1)); color: var(--accent, #059669); }
.sb-badge-red { background: color-mix(in oklab, var(--danger, #dc2626) 10%, transparent); color: var(--danger, #dc2626); }
.sb-badge-yellow { background: color-mix(in oklab, var(--warn, #d97706) 10%, transparent); color: var(--warn, #d97706); }
.sb-badge-blue { background: color-mix(in oklab, var(--info, #3b82f6) 10%, transparent); color: var(--info, #2563eb); }
.sb-badge-gray { background: color-mix(in oklab, var(--fg, #1c1c1c) 6%, transparent); color: var(--muted, #6b6b6b); }

/* sb-page-header \2014  Light mode */
.sb-page-header { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 0; border-bottom: 1px solid var(--border-soft, #ebebeb); margin-bottom: 24px; }
.sb-page-header-left { display: flex; align-items: center; gap: 12px; }
.sb-page-icon { width: 32px; height: 32px; border-radius: var(--radius-sm, 6px); display: flex; align-items: center; justify-content: center; font-size: 15px; flex-shrink: 0; }
.sb-page-title { font-size: 18px; font-weight: 400; color: var(--fg, #1c1c1c); line-height: 1.3; }
.sb-page-subtitle { font-size: 12px; color: var(--muted, #6b6b6b); }
.sb-page-header-right { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }

/* sb-toolbar \2014  Light mode */
.sb-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.sb-toolbar-left, .sb-toolbar-right { display: flex; align-items: center; gap: 8px; }

/* sb-link \2014  Light mode */
.sb-link { color: var(--accent-hover, #00c573); }
.sb-link:hover { opacity: 0.8; text-decoration: underline; }

/* sb-dot \2014  Light mode */
.sb-dot { width: 6px; height: 6px; border-radius: 50%; display: inline-block; }
.sb-dot-green { background: var(--accent, #3ecf8e); }
.sb-dot-red { background: var(--danger, #ef4444); }
.sb-dot-yellow { background: var(--warn, #f59e0b); }

/* sb-space utilities \2014  Light mode */
.sb-space-y-4 > * + * { margin-top: 16px; }
.sb-space-y-6 > * + * { margin-top: 24px; }
.sb-space-y-8 > * + * { margin-top: 32px; }

/* sb-grid \2014  Light mode */
.sb-grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
@media (max-width: 1200px) { .sb-grid-4 { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .sb-grid-4 { grid-template-columns: 1fr; } }
.sb-grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
@media (max-width: 600px) { .sb-grid-2 { grid-template-columns: 1fr; } }

/* sb-divider \2014  Light mode */
.sb-divider { height: 1px; background: var(--border-soft, #ebebeb); border: none; margin: 16px 0; }

/* =====================================================
   SB-* DARK MODE OVERRIDES
   ===================================================== */

/* sb-btn */
.dark .sb-btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: 8px; font-size: 14px; font-weight: 500;
  font-family: var(--font-display, "Inter"), system-ui, sans-serif;
  padding: 8px 24px; border: 1px solid transparent;
  cursor: pointer; border-radius: var(--radius-sm, 6px);
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.dark .sb-btn-primary {
