/* \2500 \2500 \2500  Topnav / Breadcrumbs \2500 \2500 \2500  */
.topnav{position:sticky;top:0;z-index:50;height:44px;display:flex;align-items:center;gap:8px;padding:0 var(--gutter);border-bottom:1px solid var(--border);background:var(--bg);backdrop-filter:blur(12px)}
.tn-brand{display:flex;align-items:center;gap:6px;font-size:14px;font-weight:500;color:var(--fg)}
.tn-brand svg{color:var(--accent)}
.tn-sep{width:1px;height:18px;background:var(--border);margin:0 6px}
.tn-crumbs{display:flex;align-items:center;gap:4px;font-size:13px;color:var(--muted)}
.tn-crumbs span:last-child{color:var(--fg)}
.tn-right{margin-left:auto;display:flex;align-items:center;gap:6px;padding-right:12px;margin-right:4px}

