/* \2500 \2500 \2500  Accordion rows \2500 \2500 \2500  */
.accordion-row{cursor:pointer}
.accordion-row td .accord-toggle{display:inline-flex;align-items:center;gap:4px;transition:transform 200ms;color:var(--muted);font-size:10px;margin-right:4px}
.accordion-row.is-open td .accord-toggle{transform:rotate(90deg)}
.accordion-row.is-open + .accordion-detail{display:table-row}
.accordion-detail{display:none}
.accordion-detail td{padding:0;background:var(--surface-2)}
.accordion-detail .inner{padding:12px 14px 12px 48px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px}
.accordion-detail .inner h4{font-size:12px;color:var(--fg-2);font-weight:500;margin-bottom:6px}
.accordion-detail .inner p{font-size:12px;color:var(--muted);line-height:1.6}
.accordion-detail .inner .stat{font-family:var(--font-mono);font-size:13px;color:var(--fg-2)}
.accordion-detail .inner .badge-row{display:flex;gap:4px;flex-wrap:wrap;margin-top:4px}

/* \2500 \2500 \2500  DataTables \2500 \2500 \2500  */
.table-wrap{overflow-x:auto}
.tb-table{width:100%;border-collapse:collapse;font-size:13px}
.tb-table thead{background:var(--surface-2);border-bottom:1px solid var(--border)}
.tb-table th{text-align:left;padding:10px 14px;font-weight:500;font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;white-space:nowrap;border-right:1px solid var(--border-soft);user-select:none;cursor:pointer;transition:var(--motion-fast);position:relative}
.tb-table th:last-child{border-right:none}
.tb-table th:hover{color:var(--fg-2)}
.tb-table th .sort-arrow{display:inline-block;margin-left:4px;opacity:.3;font-size:9px}
.tb-table th.is-sorted .sort-arrow{opacity:1;color:var(--accent)}
.tb-table th.check-col{width:36px;text-align:center;cursor:default}
.tb-table th.check-col:hover{color:var(--muted)}
.tb-table td{padding:10px 14px;border-bottom:1px solid var(--border-soft);vertical-align:middle;color:var(--fg)}
.tb-table tr:last-child td{border-bottom:none}
.tb-table tr:hover td{background:var(--surface-2)}
.tb-table tr.is-selected td{background:var(--accent-soft)}
.tb-table td.check-col{width:36px;text-align:center}
.tb-table td .mono{font-family:var(--font-mono);font-size:12px;color:var(--muted)}
.tb-table td .num{font-family:var(--font-mono);font-size:12px;color:var(--fg-2);text-align:right;tab-size:4}
.tb-table td .cell-flex{display:flex;align-items:center;gap:8px}
.tb-table td .cell-flex .av{width:26px;height:26px;border-radius:var(--radius-sm);display:grid;place-items:center;font-size:10px;font-weight:600;flex-shrink:0}

/* Sorting indicator */
.tb-table th .sort-wrap{display:inline-flex;align-items:center;gap:4px}
.tb-table th .sort-icons{display:inline-flex;flex-direction:column;line-height:1;opacity:.3;font-size:8px;margin-left:2px;color:var(--meta)}
.tb-table th.is-sorted-asc .sort-icons .up{color:var(--accent);opacity:1}
.tb-table th.is-sorted-desc .sort-icons .down{color:var(--accent);opacity:1}

/* Pagination */
.tb-pagination{display:flex;align-items:center;justify-content:space-between;padding:var(--space-3) var(--space-5);border-top:1px solid var(--border-soft);flex-wrap:wrap;gap:8px}
.tb-pagination .info{font-size:12px;color:var(--muted)}
.tb-pagination .pages{display:flex;align-items:center;gap:2px}
.tb-pagination .pages .page{width:28px;height:28px;display:grid;place-items:center;border-radius:var(--radius-sm);font-size:12px;color:var(--fg-2);cursor:pointer;transition:var(--motion-fast);border:1px solid transparent}
.tb-pagination .pages .page:hover{border-color:var(--border);background:var(--surface-2)}
.tb-pagination .pages .page.is-active{background:var(--accent-soft);border-color:var(--accent-border);color:var(--accent)}
.tb-pagination .pages .page.dots{color:var(--meta);cursor:default}
.tb-pagination .pages .page.dots:hover{border-color:transparent;background:none}
.tb-pagination .per-page{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)}
.tb-pagination .per-page select{padding:3px 6px;border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--bg);color:var(--fg);font-size:11px;font-family:var(--font-mono);outline:none}
.tb-pagination .per-page select:focus{border-color:var(--accent);box-shadow:var(--focus-ring)}

/* \2500 \2500 \2500  Table variants nav \2500 \2500 \2500  */
.var-nav{display:flex;gap:6px;margin-bottom:24px;flex-wrap:wrap}
.var-nav a{padding:6px 14px;border:1px solid var(--border);border-radius:var(--radius-pill);font-size:12px;color:var(--fg-2);cursor:pointer;transition:var(--motion-fast);text-decoration:none}
.var-nav a:hover{border-color:var(--accent-border);color:var(--accent)}
.var-nav a.is-active{background:var(--accent-soft);border-color:var(--accent-border);color:var(--accent)}

/* \2500 \2500 \2500  Toolbar \2500 \2500 \2500  */
.toolbar{display:flex;align-items:center;gap:8px;padding:10px 16px;flex-wrap:wrap;min-height:52px}
.toolbar .spacer{flex:1}
.toolbar select,
.toolbar .select-wrap {
  width: auto !important;
  min-width: 130px;
  max-width: 250px;
}
.btn{display:inline-flex;align-items:center;gap:6px;padding:6px 14px;border:1px solid var(--border);border-radius:var(--radius-sm, 6px) !important;background:var(--surface);color:var(--fg-2);font-size:12px;font-family:var(--font-body);cursor:pointer;transition:var(--motion-fast);white-space:nowrap;text-decoration:none}
.btn:hover{border-color:var(--border-strong);color:var(--fg);background:var(--surface-2)}
.btn-primary{background:var(--accent);border-color:var(--accent);color:var(--accent-on)}
.btn-primary:hover{background:var(--accent-hover);border-color:var(--accent-hover)}
.btn-ghost{border-color:transparent;background:transparent}
.btn-ghost:hover{border-color:var(--border);background:var(--surface)}
.btn-danger{color:var(--danger)}
.btn-danger:hover{border-color:var(--danger);color:var(--danger);background:color-mix(in oklab,var(--danger),transparent 92%)}
.btn-icon{padding:6px;min-width:30px;justify-content:center}
.btn-sm{padding:4px 10px;font-size:11px}
.btn-pill{border-radius:var(--radius-pill)}
.btn:disabled{opacity:.4;pointer-events:none}

/* \2500 \2500 \2500  Input Wrap \2500 \2500 \2500  */
.input-wrap{display:flex;align-items:center;gap:6px;padding:5px 10px;border:1px solid var(--border);border-radius:var(--radius-pill);background:var(--bg);min-width:200px;transition:var(--motion-fast)}
.input-wrap:focus-within{border-color:var(--accent);box-shadow:var(--focus-ring)}
.input-wrap input{background:none;border:none;outline:none;color:var(--fg);font-size:13px;font-family:var(--font-body);width:100%}
.input-wrap input::placeholder{color:var(--meta)}
.input-wrap svg{color:var(--muted);flex-shrink:0;width:14px;height:14px}

/* \2500 \2500 \2500  Badges \2500 \2500 \2500  */
.badge{display:inline-flex;align-items:center;gap:4px;padding:2px 8px;border-radius:var(--radius-pill);font-size:11px;font-weight:500;background:var(--surface-2);color:var(--fg-2);border:1px solid var(--border)}
.badge .dot{width:6px;height:6px;border-radius:50%;background:var(--meta)}
.badge-success{background:color-mix(in oklab,var(--success),transparent 88%);border-color:color-mix(in oklab,var(--success),transparent 70%);color:var(--success)}
.badge-success .dot{background:var(--success)}
