    /* TTSC Custom Select Styling & Dark Mode Tokens */
    .ttsc-select-wrapper {
      position: relative;
      width: 100%;
    }
    .ttsc-select-trigger {
      cursor: pointer;
      user-select: none;
    }
    .ttsc-select-dropdown {
      scrollbar-width: thin;
      scrollbar-color: #475569 transparent;
      animation: ttscDropdownFadeIn 0.15s cubic-bezier(0.16, 1, 0.3, 1);
      transform-origin: top;
    }
    @keyframes ttscDropdownFadeIn {
      from {
        opacity: 0;
        transform: scale(0.97) translateY(-4px);
      }
      to {
        opacity: 1;
        transform: scale(1) translateY(0);
      }
    }
    .ttsc-select-dropdown::-webkit-scrollbar {
      width: 4px;
    }
    .ttsc-select-dropdown::-webkit-scrollbar-thumb {
      background-color: #cbd5e1;
      border-radius: 4px;
    }
    html.dark .ttsc-select-dropdown::-webkit-scrollbar-thumb {
      background-color: #3b3e4f;
    }
    html.dark .ttsc-select-trigger {
      background-color: #1a1b20 !important;
      border-color: #2c2e39 !important;
      color: #ffffff !important;
    }
    html.dark .ttsc-select-trigger .text-slate-800 {
      color: #ffffff !important;
    }
    html.dark .ttsc-select-dropdown {
      background-color: #16171b !important;
      border-color: #2c2e39 !important;
      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.85) !important;
    }
    html.dark .ttsc-select-dropdown .border-slate-100 {
      border-color: #23252e !important;
    }
    html.dark .ttsc-select-item:not(.is-selected) {
      color: #cbd5e1 !important;
    }
    html.dark .ttsc-select-item:not(.is-selected):hover {
      background-color: #22242c !important;
      color: #ffffff !important;
    }
    html.dark .ttsc-select-item.is-selected {
      background-color: rgba(16, 185, 129, 0.18) !important;
      border-color: rgba(16, 185, 129, 0.4) !important;
      color: #34d399 !important;
    }
    /* Toast System Animations */
    @keyframes toastSlideIn {
      from { transform: translateX(110%); opacity: 0; }
      to { transform: translateX(0); opacity: 1; }
    }
    @keyframes toastSlideOut {
      from { transform: translateX(0); opacity: 1; }
      to { transform: translateX(110%); opacity: 0; }
    }
    .toast-enter {
      animation: toastSlideIn 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
    }
    .toast-exit {
      animation: toastSlideOut 0.25s cubic-bezier(0.16, 1, 0.3, 1) forwards;
