      width: calc(100% - 14px) !important;
      justify-content: flex-start !important;
    }
    #primary-rail .rail-label {
      opacity: 0;
      max-width: 0;
      overflow: hidden;
      white-space: nowrap;
      transition: opacity 0.18s ease, max-width 0.22s ease;
      pointer-events: none;
    }
