.shell.is-rail-pinned .rail-ttsc-btn .rail-label,
.shell.is-rail-pinned .rail-btn .rail-label,
.rail.is-open .rail-ttsc-btn .rail-label,
.rail.is-open .rail-btn .rail-label,
.rail.is-mobile-open .rail-ttsc-btn .rail-label,
.rail.is-mobile-open .rail-btn .rail-label {
