}

@media (hover: hover) {
  .rail:hover .rail-ttsc-btn,
  .rail:hover .rail-btn {
    width: 100%;
    min-width: 0;
    height: 38px;
    min-height: 38px;
    margin: 2px 0;
    padding: 0 12px;
    justify-content: flex-start;
  }
  .rail:hover .rail-ttsc-btn .rail-icon,
  .rail:hover .rail-btn .rail-icon {
    margin: 0 10px 0 0;
    flex: 0 0 18px;
    width: 18px;
    justify-content: flex-start;
  }
  .rail:hover .rail-ttsc-btn .rail-label,
  .rail:hover .rail-btn .rail-label {
    opacity: 1; max-width: 190px;
    transition-delay: 40ms;
  }
  .rail:hover .rail-ttsc-btn:nth-child(2) .rail-label,
  .rail:hover .rail-btn:nth-child(2) .rail-label { transition-delay: 55ms; }
  .rail:hover .rail-ttsc-btn:nth-child(3) .rail-label,
  .rail:hover .rail-btn:nth-child(3) .rail-label { transition-delay: 70ms; }
  .rail:hover .rail-ttsc-btn:nth-child(4) .rail-label,
  .rail:hover .rail-btn:nth-child(4) .rail-label { transition-delay: 85ms; }
  .rail:hover .rail-ttsc-btn:nth-child(5) .rail-label,
  .rail:hover .rail-btn:nth-child(5) .rail-label { transition-delay: 100ms; }
  .rail:hover .rail-ttsc-btn:nth-child(6) .rail-label,
  .rail:hover .rail-btn:nth-child(6) .rail-label { transition-delay: 115ms; }
  .rail:hover .rail-ttsc-btn:nth-child(n+7) .rail-label,
  .rail:hover .rail-btn:nth-child(n+7) .rail-label { transition-delay: 130ms; }
}
.rail-spacer { flex: 1; min-height: 8px; }

/* Hide mobile header inside rail by default on Desktop/Web */
.rail-mobile-header {
  display: none !important;
}

/* \2500 \2500 \2500  sub-sidebar (fixa, 280px) \2500 \2500 \2500  */
.sidebar {
  grid-column: 2; grid-row: 2;
  background: var(--bg);
  border-right: 1px solid var(--border);
  padding: 0;
  overflow-x: hidden; overflow-y: auto;
  position: sticky; top: var(--topnav-h);
  height: calc(100vh - var(--topnav-h));
  width: 100%;
  display: flex; flex-direction: column;
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
  z-index: 20;
}
.sidebar::-webkit-scrollbar { width: 6px; }
.sidebar::-webkit-scrollbar-track { background: transparent; }
.sidebar::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: var(--radius-pill, 9999px);
}
.sidebar::-webkit-scrollbar-thumb:hover { background: var(--meta); }

/* sidebar sections/items */
.sb-section { padding: 0 8px; }
.sb-section + .sb-section { margin-top: 8px; }

.sb-section-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 6px 10px;
  background: transparent; border: 0;
  font-family: var(--font-mono, monospace); font-size: 11px;
  letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--muted);
  cursor: pointer;
  min-height: 44px;
  white-space: nowrap; overflow: hidden;
  transition: color var(--motion-fast, 150ms) var(--ease-standard, ease);
}
.sb-section-toggle:hover { color: var(--fg); }
.sb-section-toggle .sb-text {
  flex: 1 1 auto; min-width: 0;
  opacity: 1; max-width: 200px; overflow: hidden; text-align: left;
}
.sb-chevron {
  font-size: 10px; /* made smaller */
  flex: 0 0 auto;
  color: var(--muted); /* made muted */
  opacity: 0.7;
  transition: transform var(--motion-base, 200ms) cubic-bezier(0.34, 1.56, 0.64, 1);
}
.sb-toggle-icon {
  width: 14px; text-align: center; color: var(--muted);
  transition: color var(--motion-fast, 150ms) var(--ease-standard, ease);
}
.sb-section-toggle:hover .sb-toggle-icon { color: var(--fg); }
.sb-section.is-collapsed .sb-chevron { transform: rotate(-90deg); }
.sb-section.is-collapsed .sb-subsection {
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  padding-top: 0;
  padding-bottom: 0;
  margin-top: 0;
  margin-bottom: 0;
}
.sb-subsection {
  max-height: 3000px;
  opacity: 1;
  overflow: hidden;
  transition: max-height var(--motion-slow, 360ms) cubic-bezier(0.16, 1, 0.3, 1),
              opacity var(--motion-base, 200ms) cubic-bezier(0.16, 1, 0.3, 1),
              padding var(--motion-fast, 150ms) ease,
              margin var(--motion-fast, 150ms) ease;
}

.sb-item.sb-leaf {
  padding-left: 32px;
  font-size: 12.5px;
  color: var(--fg-2);
}
.sb-item.sb-leaf::before {
  content: ""; width: 3px; height: 3px; border-radius: 50%;
  background: var(--meta); margin-right: 8px; flex: 0 0 auto;
}
.sb-item.sb-leaf:hover { color: var(--fg); }

.sb-count {
  flex: 0 0 auto;
  font-family: var(--font-mono, monospace); font-size: 10px;
  color: var(--muted);
  padding: 1px 6px; border-radius: var(--radius-pill, 9999px);
  border: 1px solid var(--border);
}
.sb-label {
  font-family: var(--font-mono, monospace); font-size: 11px;
  letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--muted); padding: 8px 10px; margin: 0;
  white-space: nowrap; overflow: hidden;
}
.sb-item {
  display: flex; align-items: center; gap: 8px;
  min-height: 44px; padding: 7px 10px; border-radius: var(--radius-sm, 6px);
  font-size: 13px; color: var(--fg-2); background: transparent;
  border: 1px solid transparent; text-align: left; width: 100%;
  white-space: nowrap; overflow: hidden; position: relative;
  transition: background var(--motion-fast, 150ms) cubic-bezier(0.16, 1, 0.3, 1),
              color var(--motion-fast, 150ms) cubic-bezier(0.16, 1, 0.3, 1),
              border-color var(--motion-fast, 150ms) cubic-bezier(0.16, 1, 0.3, 1);
}
.sb-item:hover {
  background: var(--surface);
  color: var(--fg);
  border-color: var(--border);
}
.sb-item.is-active {
  background: var(--surface);
  color: var(--fg);
  border-color: var(--border);
}
.sb-item .icon {
  width: 16px; height: 16px; flex: 0 0 auto; color: var(--muted);
  transition: color var(--motion-fast, 150ms) ease;
}
.sb-item:hover .icon {
  color: var(--fg);
}
.sb-item.is-active .icon { color: var(--accent); }
.sb-item .sb-text {
  flex: 1 1 auto; min-width: 0;
  opacity: 1; max-width: 200px; overflow: hidden;
}
.sb-item .pill-tag {
  flex: 0 0 auto;
  font-size: 9.5px; font-family: var(--font-mono, monospace);
  letter-spacing: 0.08em; text-transform: uppercase;
  padding: 1px 6px; border-radius: var(--radius-pill, 9999px);
  border: 1px solid color-mix(in oklab, var(--warn) 50%, transparent);
  color: var(--warn);
}
.sb-item.sb-sub { padding-left: 22px; font-size: 13px; }
.sb-item.sb-sub::before {
  content: ""; width: 4px; height: 4px; border-radius: 50%;
  background: var(--meta); margin-right: 6px; flex: 0 0 auto;
}

/* sidebar header */
.sb-header {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  padding: 10px 10px; border-bottom: 1px solid var(--border-soft);
  position: sticky; top: 0; background: var(--bg); z-index: 2; min-height: 40px;
}
.sb-header-title {
  display: flex; align-items: center; gap: 8px; min-width: 0;
  font-size: 14px; font-weight: 500; color: var(--fg);
  white-space: nowrap; overflow: hidden;
}
.sb-header-icon { width: 16px; height: 16px; flex: 0 0 auto; color: var(--accent); }
.sb-header-action {
  width: 44px; height: 44px; display: grid; place-items: center;
  background: transparent; border: 1px solid transparent;
  border-radius: var(--radius-sm, 6px); color: var(--muted); flex: 0 0 auto;
  transition: background var(--motion-fast, 150ms) var(--ease-standard, ease),
              color var(--motion-fast, 150ms) var(--ease-standard, ease);
}
.sb-header-action:hover { background: var(--surface); color: var(--fg); }
.sb-header-action svg { width: 13px; height: 13px; }

/* sidebar search header wrapper */
.sb-search-wrapper {
  padding: 10px 16px !important;
  background: var(--surface, #ffffff) !important;
  border-bottom: 1px solid var(--border, #e4e4e7) !important;
  position: sticky !important;
  top: 0 !important;
  z-index: 10 !important;
  width: 100% !important;
  box-sizing: border-box !important;
}
.dark .sb-search-wrapper {
  background: var(--surface-dark, var(--bg)) !important;
  border-bottom-color: var(--border-dark, var(--border)) !important;
}

.sb-search {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  margin: 0 !important;
  width: 100% !important;
  height: 36px !important;
  padding: 0 12px !important;
  border-radius: 9999px !important;
  background: var(--surface-hover, #f4f4f5) !important;
  border: 1px solid var(--border, #e4e4e7) !important;
  color: var(--fg, #18181b) !important;
  position: static !important;
  box-sizing: border-box !important;
  transition: border-color var(--motion-fast, 150ms) ease, box-shadow var(--motion-fast, 150ms) ease !important;
}
.dark .sb-search {
  background: var(--surface) !important;
  border-color: var(--border) !important;
  color: var(--fg) !important;
}
.sb-search:focus-within,
.sb-search:hover {
  border-color: var(--accent) !important;
  box-shadow: 0 0 0 2px var(--focus-ring) !important;
}
.sb-search-icon { width: 13px; height: 13px; color: var(--muted); flex: 0 0 auto; transition: color var(--motion-fast, 150ms) ease; }
.sb-search:focus-within .sb-search-icon { color: var(--accent); }
.sb-search input {
  flex: 1; min-width: 0;
  background: transparent; border: 0; outline: 0;
  font: inherit; font-size: 12.5px; color: var(--fg);
}
.sb-search input::placeholder { color: var(--muted); }

/* Keyboard shortcut hint inside search bar */
.sb-kbd-hint {
  flex: 0 0 auto;
  font-family: var(--font-mono, "SF Mono", "Source Code Pro", monospace);
  font-size: 9.5px;
  color: var(--muted);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 5px;
  line-height: 1.4;
  pointer-events: none;
  user-select: none;
  opacity: 0.8;
  transition: opacity var(--motion-fast, 150ms) ease;
}
.sb-search:focus-within .sb-kbd-hint,
.sb-search:hover .sb-kbd-hint {
  opacity: 0.35;
}

/* \2500 \2500 \2500  sidebar search animations \2500 \2500 \2500  */

/* Items fade out when hidden by search */
.sb-item {
  transition: background var(--motion-fast, 150ms) cubic-bezier(0.16, 1, 0.3, 1),
              color var(--motion-fast, 150ms) cubic-bezier(0.16, 1, 0.3, 1),
              border-color var(--motion-fast, 150ms) cubic-bezier(0.16, 1, 0.3, 1),
              transform var(--motion-fast, 150ms) cubic-bezier(0.34, 1.56, 0.64, 1),
              opacity var(--motion-base, 220ms) cubic-bezier(0.16, 1, 0.3, 1),
              max-height var(--motion-base, 220ms) cubic-bezier(0.16, 1, 0.3, 1),
              padding var(--motion-fast, 150ms) ease,
              margin var(--motion-fast, 150ms) ease,
              border-width var(--motion-fast, 150ms) ease;
  max-height: 80px;
}
.sb-item.sb-search-hidden {
  opacity: 0;
  max-height: 0;
  padding-top: 0;
  padding-bottom: 0;
  margin-top: 0;
  margin-bottom: 0;
  border-width: 0;
  overflow: hidden;
  pointer-events: none;
}

/* Sections fade out when all children are hidden */
.sb-section {
  transition: opacity var(--motion-slow, 300ms) cubic-bezier(0.16, 1, 0.3, 1),
              max-height var(--motion-slow, 300ms) cubic-bezier(0.16, 1, 0.3, 1),
              padding var(--motion-base, 200ms) ease,
              margin var(--motion-base, 200ms) ease;
  max-height: 3000px;
  overflow: hidden;
}
.sb-section.sb-search-hidden {
  opacity: 0;
  max-height: 0;
  padding-top: 0;
  padding-bottom: 0;
  margin-top: 0;
  margin-bottom: 0;
  pointer-events: none;
}

/* Dividers fade out between hidden sections */
.sb-divider {
  transition: opacity var(--motion-base, 200ms) cubic-bezier(0.16, 1, 0.3, 1),
              max-height var(--motion-base, 200ms) cubic-bezier(0.16, 1, 0.3, 1),
              margin var(--motion-base, 200ms) ease;
  overflow: hidden;
}
.sb-divider.sb-search-hidden {
  opacity: 0;
  max-height: 0;
  margin-top: 0;
  margin-bottom: 0;
  border-width: 0;
  pointer-events: none;
}

/* sidebar search no-results message - fade in/out */
@keyframes sbMsgIn {
  from { opacity: 0; transform: translateY(-8px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes sbMsgOut {
  from { opacity: 1; transform: translateY(0) scale(1); }
  to   { opacity: 0; transform: translateY(-8px) scale(0.97); }
}
.sb-search-msg {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 12px; font-size: 13px; color: var(--muted);
  animation: sbMsgIn 200ms cubic-bezier(0.16, 1, 0.3, 1) both;
}
.sb-search-msg.sb-search-msg-exit {
  animation: sbMsgOut 150ms cubic-bezier(0.16, 1, 0.3, 1) both;
}
.sb-search-msg span { opacity: 0.8; }
.sb-search-clear {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: 6px; padding: 4px 10px; font-size: 11px;
  cursor: pointer; color: var(--fg-2);
  transition: background var(--motion-fast, 150ms) var(--ease-standard, ease),
              color var(--motion-fast, 150ms) var(--ease-standard, ease);
}
.sb-search-clear:hover { background: var(--bg); color: var(--fg); }
.sb-content { padding: 4px 0 16px; }

/* sidebar close/open buttons (mobile) */
.sb-close-ttsc-btn,
.sb-close-btn {
  display: none;
  width: 24px; height: 24px;
  background: transparent; border: 1px solid transparent;
  border-radius: var(--radius-sm, 6px); color: var(--muted);
  place-items: center;
  cursor: pointer;
  transition: background var(--motion-fast, 150ms) var(--ease-standard, ease),
              color var(--motion-fast, 150ms) var(--ease-standard, ease),
              border-color var(--motion-fast, 150ms) var(--ease-standard, ease);
}
.sb-close-ttsc-btn:hover,
.sb-close-btn:hover {
  background: var(--surface);
  color: var(--fg);
  border-color: var(--border);
}
.sb-open-btn {
  display: none;
  position: fixed; z-index: 26;
  top: calc(var(--topnav-h) + 12px);
  left: calc(var(--rail-w) + 4px);
  width: 24px; height: 32px;
  background: var(--surface); border: 1px solid var(--border);
  border-radius: 0 var(--radius-sm, 6px) var(--radius-sm, 6px) 0;
  color: var(--muted); font-size: 10px;
  place-items: center;
  transition: background var(--motion-fast, 150ms) var(--ease-standard, ease);
}
.sb-open-btn:hover { background: var(--bg); color: var(--fg); }

/* sidebar backdrop (mobile) */
.sb-backdrop {
  position: fixed; inset: 0; z-index: 24;
  background: var(--scrim, rgba(0,0,0,0.5));
  opacity: 0; pointer-events: none;
  transition: opacity var(--motion-base, 200ms) cubic-bezier(0.16, 1, 0.3, 1),
              backdrop-filter var(--motion-slow, 360ms) cubic-bezier(0.16, 1, 0.3, 1);
  will-change: opacity, backdrop-filter;
}
@supports (backdrop-filter: blur(2px)) or (-webkit-backdrop-filter: blur(2px)) {
  .sb-backdrop { backdrop-filter: blur(0px); -webkit-backdrop-filter: blur(0px); }
  .sb-backdrop.is-open {
    backdrop-filter: blur(2px);
    -webkit-backdrop-filter: blur(2px);
  }
}
.sb-backdrop.is-open {
  opacity: 1;
  pointer-events: auto;
  transition: opacity var(--motion-base, 200ms) cubic-bezier(0.16, 1, 0.3, 1),
              backdrop-filter var(--motion-slow, 360ms) cubic-bezier(0.16, 1, 0.3, 1);
}

/* \2500 \2500 \2500  main content \2500 \2500 \2500  */
.content {
  grid-column: 2; grid-row: 2;
  min-width: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  min-height: calc(100vh - var(--topnav-h, 56px));
}
.shell.has-sub .content {
  grid-column: 3;
}
.content-inner {
  flex: 1 0 auto;
  max-width: 100%;
  margin: 0;
  padding: 0 0 32px !important;
  display: flex;
  flex-direction: column;
  gap: 0;
}
/* Override inline margin-top on direct children \2014  the flex gap handles spacing */
.content-inner > .wg,
.content-inner > .tb-card,
.content-inner > div[style*="margin-top"],
.content-inner > .ttsc-container-fluid {
  margin-top: 0 !important;
}

/* \2500 \2500 \2500  page header \2500 \2500 \2500  */
.page-head {
  padding: 12px 0;
  border-bottom: 1px solid var(--border);
  margin-bottom: 0;
}
.page-head .eyebrow {
  font-family: var(--font-mono, monospace); font-size: 11px; letter-spacing: 0.1em;
  text-transform: uppercase; color: var(--accent); margin: 0 0 12px;
}
.page-head h1 {
  font-family: var(--font-sans);
  font-size: clamp(32px, 4vw, 48px);
  line-height: 1.1; letter-spacing: -0.015em; margin: 0 0 12px;
  font-weight: 400; color: var(--fg);
}
.page-head p { color: var(--muted); font-size: 16px; margin: 0; max-width: 64ch; }

/* \2500 \2500 \2500  divider \2500 \2500 \2500  */
.sb-divider {
  border: 0; border-top: 1px solid var(--border);
  margin: 16px calc(-1 * var(--container-gutter-desktop, 24px));
  width: calc(100% + calc(2 * var(--container-gutter-desktop, 24px)));
}

/* \2500 \2500 \2500  crumb dropdown \2500 \2500 \2500  */
.tn-crumb-group { position: relative; }
.tn-crumb-menu {
  position: absolute; top: calc(100% + 8px); left: 0;
  min-width: 200px; padding: 6px;
  background: var(--surface, #1c1c1c); border: 1px solid var(--border);
  border-radius: var(--radius-md, 8px);
  box-shadow: var(--elev-raised, 0 4px 12px rgba(0,0,0,0.3));
  opacity: 0; visibility: hidden;
  transform: translateY(-4px);
  transition: opacity var(--motion-fast, 150ms) var(--ease-standard, ease),
              transform var(--motion-fast, 150ms) var(--ease-standard, ease),
              visibility var(--motion-fast, 150ms);
  z-index: 50;
}
.tn-crumb-group.open .tn-crumb-menu { opacity: 1; visibility: visible; transform: none; }
.tn-crumb-search {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 12px; margin-bottom: 8px;
  background: var(--bg); border: 1px solid var(--border);
  border-radius: 9999px;
}
.tn-crumb-search svg { color: var(--muted); flex: 0 0 auto; width: 15px; height: 15px; }
.tn-crumb-search input {
  background: transparent; border: 0; outline: none;
  color: var(--fg); font-size: 13.5px; width: 100%;
}
.tn-crumb-search input::placeholder { color: var(--muted); }
.tn-crumb-list { max-height: 250px; overflow-y: auto; scrollbar-width: thin; margin: 0 -6px; padding: 0 6px; }
.tn-crumb-list::-webkit-scrollbar { width: 4px; }
.tn-crumb-list::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }
.tn-crumb-menu-item {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 8px 10px; font-size: 13px; color: var(--fg-2);
  border-radius: 4px; cursor: pointer; text-decoration: none;
  transition: background var(--motion-fast, 150ms) var(--ease-standard, ease),
              color var(--motion-fast, 150ms) var(--ease-standard, ease);
}
.tn-crumb-item-content { display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tn-crumb-menu-item:hover { background: var(--surface); color: var(--fg); }
.tn-crumb-menu-item:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring, 0 0 0 2px rgba(62, 207, 142, 0.5));
}
.tn-crumb-menu-item.active { background: var(--surface); color: var(--fg); font-weight: 500; }
.tn-crumb-check { color: var(--fg); display: none; flex: 0 0 auto; }
.tn-crumb-menu-item.active .tn-crumb-check { display: block; }
.tn-crumb-menu-sep { border-top: 1px solid var(--border); margin: 6px -6px; }

/* =====================================================
   USER DROPDOWN (inside topnav)
   ===================================================== */
.sb-user-dropdown { position: relative; margin-right: 5px; }
.sb-user-menu {
  position: absolute; top: calc(100% + 8px); right: 0;
  min-width: 200px; padding: 6px;
  background: var(--surface, #1c1c1c); border: 1px solid var(--border);
  border-radius: var(--radius-md, 8px);
  box-shadow: var(--elev-raised, 0 4px 12px rgba(0,0,0,0.3));
  opacity: 0; visibility: hidden;
  transform: translateY(-4px);
  transition: opacity var(--motion-fast, 150ms) var(--ease-standard, ease),
              transform var(--motion-fast, 150ms) var(--ease-standard, ease),
              visibility var(--motion-fast, 150ms);
  z-index: 50;
}
.sb-user-dropdown.open .sb-user-menu { opacity: 1; visibility: visible; transform: none; }
.sb-user-menu-header {
  padding: 8px 16px 12px; border-bottom: 1px solid var(--border);
  margin: 0 -6px 6px -6px;
}
.sb-user-menu-name { margin: 0; font-size: 13px; font-weight: 500; color: var(--fg); }
.sb-user-menu-email { margin: 2px 0 0; font-size: 11px; color: var(--muted); }
.sb-user-menu-item {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 16px; font-size: 13px; color: var(--fg-2);
  border-radius: 4px; cursor: pointer; text-decoration: none;
  transition: background var(--motion-fast, 150ms) var(--ease-standard, ease),
              color var(--motion-fast, 150ms) var(--ease-standard, ease);
  margin: 0 -6px;
}
.sb-user-menu-item:hover { background: var(--surface); color: var(--fg); }
.sb-user-menu-item:focus-visible {
