/* Grouped portal navigation: native disclosure, keyboard and touch friendly. */
#primary-rail .portal-rail-group { width: 100%; border-top: 1px solid var(--border-color, #e2e8f0); padding-top: 4px; }
/* The border is a separator BETWEEN groups: the first group has nothing above it, so no stray top line. */
#primary-rail .portal-rail-group:first-child { border-top: none; padding-top: 0; }
#primary-rail .portal-rail-group summary { display: flex; align-items: center; min-height: 36px; border-radius: 8px; cursor: pointer; color: #64748b; list-style: none; }
#primary-rail .portal-rail-group summary::-webkit-details-marker { display: none; }
#primary-rail .portal-rail-group summary:hover { background: #f1f5f9; color: #0f172a; }
#primary-rail .portal-rail-group summary:focus-visible { outline: 2px solid #10b981; outline-offset: -2px; }
#primary-rail .portal-group-icon { width: 44px; flex-shrink: 0; text-align: center; font-size: 13px; }
#primary-rail .portal-group-label { display: none; flex: 1; min-width: 0; font-size: 10px; font-weight: 600; line-height: 1.4; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#primary-rail .portal-group-chevron { display: none; margin: 0 8px; font-size: 9px; transform: rotate(-90deg); }
#primary-rail details[open] > summary .portal-group-chevron { transform: rotate(0); }
#primary-rail .portal-group-items { display: flex; flex-direction: column; align-items: center; gap: 4px; width: 100%; }
#primary-rail .portal-rail-group[open] > .portal-group-items { padding: 4px 0; }
#primary-rail details:not([open]) > .portal-group-items { display: none; }
#primary-rail:is(:hover, :focus-within) .portal-group-label,
#primary-rail:is(:hover, :focus-within) .portal-group-chevron,
#primary-rail-wrapper.is-expanded .portal-group-label,
#primary-rail-wrapper.is-expanded .portal-group-chevron { display: block; }
.sb-app #primary-rail:focus-within { width: min(288px, calc(100vw - 16px)) !important; z-index: 50 !important; box-shadow: 8px 0 28px -4px rgba(0,0,0,.14); }
.sb-app #primary-rail:focus-within .rail-item { width: calc(100% - 14px) !important; justify-content: flex-start !important; }
.sb-app #primary-rail:focus-within .rail-label { opacity: 1 !important; max-width: 230px !important; pointer-events: auto !important; }
.sb-app #primary-rail:focus-within .rail-tooltip { display: none !important; }
html.dark #primary-rail .portal-rail-group { border-color: #334155; }
html.dark #primary-rail .portal-rail-group summary { color: #94a3b8; }
html.dark #primary-rail .portal-rail-group summary:hover { background: #1e293b; color: #f1f5f9; }
@media (prefers-reduced-motion: reduce) {
  .sb-app #primary-rail, #primary-rail .rail-item, #primary-rail .rail-label { transition: none !important; }
}

/* Visibility follows the rail's actual width, including during transitions.
   Hover/focus can remain active while a page-specific layout constrains it. */
#primary-rail { container-name: portal-rail; container-type: inline-size; }
/* Preserve the design-system mobile drawers after the desktop .sb-app rules.
   Those later rules otherwise reserve 380px and leave the content off-screen. */
@media (max-width: 1099px) {
  .sb-app #primary-rail-wrapper,
  .sb-app #sub-sidebar {
    position: fixed !important;
    inset: 0 auto 0 0 !important;
    z-index: var(--ttsc-z-drawer) !important;
  }
  .sb-app #sub-sidebar {
    width: min(var(--ttsc-sub-sidebar-w), calc(100vw - 3rem)) !important;
    min-width: 0 !important;
  }
  .sb-app #main-viewport { min-width: 0; }
}
@container portal-rail (max-width: 100px) {
  #primary-rail .portal-group-label,
