  --fa-style: 300;
  font-weight: 300 !important;
}

/* Global light weight fallback for any unconverted classic solid/regular icons */
.fa-solid:not(.fa-brands):not(.fab):not([data-keep-weight]),
.fa-regular:not(.fa-brands):not(.fab):not([data-keep-weight]),
.fas:not(.fa-brands):not(.fab):not([data-keep-weight]),
