/* \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 
   TTSC CUSTOM SELECT SYSTEM (High-Fidelity Dropdown Architecture)
   \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550  */
.ttsc-select-wrapper {
  position: relative;
  width: 100%;
}
.ttsc-select-trigger {
  cursor: pointer;
  user-select: none;
}
.ttsc-select-dropdown {
  scrollbar-width: thin;
  scrollbar-color: #cbd5e1 transparent;
  animation: ttscDropdownFadeIn 0.15s cubic-bezier(0.16, 1, 0.3, 1);
  transform-origin: top;
}
@keyframes ttscDropdownFadeIn {
  from {
    opacity: 0;
    transform: scale(0.97) translateY(-4px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}
.ttsc-select-dropdown::-webkit-scrollbar {
  width: 4px;
}
.ttsc-select-dropdown::-webkit-scrollbar-thumb {
  background-color: #cbd5e1;
  border-radius: 4px;
}
html.dark .ttsc-select-dropdown::-webkit-scrollbar-thumb {
  background-color: #373943;
}
html.dark .ttsc-select-trigger {
  background-color: #1a1b20 !important;
  border-color: #2e303b !important;
  color: #f1f5f9 !important;
}
html.dark .ttsc-select-trigger .text-slate-800 {
  color: #ffffff !important;
}
html.dark .ttsc-select-dropdown {
  background-color: #16171b !important;
  border-color: #2e303b !important;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.85) !important;
}
html.dark .ttsc-select-dropdown .border-slate-100 {
  border-color: #272932 !important;
}
html.dark .ttsc-select-item:not(.is-selected) {
  color: #cbd5e1 !important;
}
html.dark .ttsc-select-item:not(.is-selected):hover {
  background-color: #23252e !important;
  color: #ffffff !important;
}
html.dark .ttsc-select-item.is-selected {
  background-color: rgba(16, 185, 129, 0.16) !important;
  border-color: #10b981 !important;
  color: #34d399 !important;
}
/* Keyboard focus (roving focus inside the listbox) */
.ttsc-select-item:focus {
  outline: none;
}
.ttsc-select-item:focus-visible:not(.is-selected) {
  background-color: #f8fafc;
  border-color: #e2e8f0 !important;
  color: #0f172a;
}
.ttsc-select-item:focus-visible {
  box-shadow: 0 0 0 2px rgba(16, 185, 129, 0.45);
}
html.dark .ttsc-select-item:focus-visible:not(.is-selected) {
  background-color: #23252e !important;
  border-color: #2e303b !important;
  color: #ffffff !important;
}
/* Disabled select / disabled option */
.ttsc-select-trigger:disabled,
.ttsc-select-trigger[aria-disabled="true"] {
  cursor: not-allowed;
  opacity: 0.55;
  background-color: #f8fafc;
}
.ttsc-select-trigger:disabled:hover {
  border-color: #e2e8f0;
}
html.dark .ttsc-select-trigger:disabled {
  opacity: 0.5;
}
.ttsc-select-item.is-disabled,
.ttsc-select-item.is-disabled:hover {
  cursor: not-allowed;
  opacity: 0.45;
  background-color: transparent !important;
}
html.dark .ttsc-select-item.is-disabled:not(.is-selected):hover {
  background-color: transparent !important;
  color: #cbd5e1 !important;
}
/* <optgroup> headers */
.ttsc-select-group-label {
  cursor: default;
}
.ttsc-select-group-label.is-disabled {
  opacity: 0.6;
}
html.dark .ttsc-select-group-label {
  color: #64748b;
}
/* Native multiple select fallback (selects that opt out of the engine) */
select[multiple].ttsc-input {
  padding: 0.25rem;
  border-radius: 0.75rem;
}
select[multiple].ttsc-input option {
  padding: 0.25rem 0.5rem;
  border-radius: 0.5rem;
}
select[multiple].ttsc-input option:checked {
  background: #ecfdf5 linear-gradient(0deg, #ecfdf5 0%, #ecfdf5 100%);
  color: #047857;
}
html.dark select[multiple].ttsc-input option:checked {
  background: rgba(16, 185, 129, 0.18) linear-gradient(0deg, rgba(16, 185, 129, 0.18) 0%, rgba(16, 185, 129, 0.18) 100%);
  color: #34d399;
}

