      background-color: #22242c !important;
      border-color: #2e313d !important;
      color: #ffffff !important;
    }
    html.dark #notif-tabs-bar button:not(.bg-emerald-50):not(.is-active):hover i {
      color: #34d399 !important;
    }
    html.dark #notif-tabs-bar button:not(.bg-emerald-50):not(.is-active):hover span:not([id^="notif-badge-"]) {
      color: #ffffff !important;
    }
    html.dark #notif-tabs-bar button:not(.bg-emerald-50):not(.is-active):hover span[id^="notif-badge-"] {
      background-color: #2a2d38 !important;
      color: #f1f5f9 !important;
      border-color: #383b4a !important;
    }
    /* Active */
    html.dark #notif-tabs-bar button.bg-emerald-50,
    html.dark #notif-tabs-bar button.is-active {
      background-color: rgba(16, 185, 129, 0.16) !important;
      border-color: rgba(16, 185, 129, 0.45) !important;
