    }
    html.dark [id^="cal-tab-btn-"]:not(.bg-emerald-50) {
      color: #94a3b8 !important;
      background-color: transparent !important;
      border-color: transparent !important;
    }
    html.dark [id^="cal-tab-btn-"]:not(.bg-emerald-50):hover {
