    }

/* ===== assets/css/ttsc.widgets.css ===== */
/* \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 
   TTSC Widgets \2014  Supabase Design System
   Extracted from widgets-supabase.html reference.
   \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550  */

/* \2500 \2500  Grid \2500 \2500  */
.wg { display: grid; gap: var(--space-4, 16px); }
.wg + .wg { margin-top: var(--space-4, 16px); }
.wg-2 { grid-template-columns: repeat(2, 1fr); }
.wg-3 { grid-template-columns: repeat(3, 1fr); }
.wg-4 { grid-template-columns: repeat(4, 1fr); }
.wg-2-1 { grid-template-columns: 2fr 1fr; }
.wg-1-2 { grid-template-columns: 1fr 2fr; }

@media (max-width: 1100px) {
  .wg-4 { grid-template-columns: repeat(2, 1fr); }
  .wg-3 { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 992px) {
  .wg-2, .wg-2-1, .wg-1-2 { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
  .wg-3, .wg-4 { grid-template-columns: 1fr; }
}

/* \2500 \2500  Widget Card \2500 \2500  */
.widget {
  background: var(--surface, #1c1c1c);
  border: 1px solid var(--border, #2e2e2e);
  border-radius: var(--radius-lg, 16px);
  padding: var(--space-5, 20px);
  position: relative;
  transition: border-color var(--motion-base, 200ms) var(--ease-standard, ease),
              box-shadow var(--motion-base, 200ms) var(--ease-standard, ease);
}
.widget:hover {
  border-color: var(--meta, #4d4d4d);
  box-shadow: var(--elev-raised, 0 0 0 1px var(--border), 0 4px 12px rgba(0,0,0,0.4));
}

/* \2500 \2500  Widget Header \2500 \2500  */
.widget-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-4, 16px);
  gap: var(--space-2, 8px);
}
.widget-title {
  display: flex;
  align-items: center;
  gap: 8px;
}
.widget-title .wt-icon {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  background: color-mix(in oklab, var(--accent, #3ecf8e) 12%, transparent);
  border-radius: var(--radius-sm, 6px);
  color: var(--accent, #3ecf8e);
  flex-shrink: 0;
}
.widget-title .wt-icon svg { width: 14px; height: 14px; }
.widget-title .wt-icon i { font-size: 13px; }
.widget-title h3 { font-size: var(--text-sm, 14px); font-weight: 500; margin: 0; }

/* wt-icon semantic variants */
.widget-title .wt-icon.is-success {
  background: color-mix(in oklab, var(--success, #16a34a) 12%, transparent);
  color: var(--success, #16a34a);
}
.widget-title .wt-icon.is-danger {
  background: color-mix(in oklab, var(--danger, #dc2626) 12%, transparent);
  color: var(--danger, #dc2626);
}
.widget-title .wt-icon.is-warn {
  background: color-mix(in oklab, var(--warn, #eab308) 12%, transparent);
  color: var(--warn, #eab308);
}
.widget-title .wt-icon.is-info {
  background: color-mix(in oklab, var(--info, #2563eb) 12%, transparent);
  color: var(--info, #2563eb);
}

/* \2500 \2500  Badge \2500 \2500  */
.widget-badge {
  font-size: 10px;
  font-family: var(--font-mono, monospace);
  text-transform: uppercase;
  letter-spacing: .06em;
  padding: 2px 8px;
  border-radius: var(--radius-pill, 9999px);
  background: var(--border-soft, #242424);
  color: var(--meta, #4d4d4d);
  white-space: nowrap;
}
.widget-badge.is-hot {
  background: color-mix(in oklab, var(--accent, #3ecf8e) 14%, transparent);
  color: var(--accent, #3ecf8e);
}

/* \2500 \2500  Separator \2500 \2500  */
.wsep { border: 0; border-top: 1px solid var(--border, #2e2e2e); margin: var(--space-4, 16px) 0; }

/* \2500 \2500  Metric Value \2500 \2500  */
.metric-value {
  font-size: var(--text-3xl, 36px);
  font-weight: 400;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  display: flex;
  align-items: baseline;
  gap: 4px;
}
.metric-value .mv-unit { font-size: var(--text-lg, 18px); color: var(--muted, #898989); }
.metric-value .mv-delta {
  font-size: 13px;
  font-weight: 500;
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 2px;
}
.mv-delta.up { color: var(--success, #16a34a); }
.mv-delta.down { color: var(--danger, #dc2626); }

/* \2500 \2500  Metric Label \2500 \2500  */
.metric-label {
  font-size: var(--text-xs, 12px);
  color: var(--muted, #898989);
  margin-top: var(--space-1, 4px);
}
.metric-label .ml-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  margin-right: 6px;
  vertical-align: middle;
}
.ml-dot.green { background: var(--accent, #3ecf8e); }
.ml-dot.yellow { background: var(--warn, #eab308); }
.ml-dot.blue { background: var(--info, #2563eb); }
.ml-dot.red { background: var(--danger, #dc2626); }
.ml-dot.pulse { animation: pulse-dot 2s ease-in-out infinite; }
@keyframes pulse-dot { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }

/* \2500 \2500  Sparkline \2500 \2500  */
.sparkline { width: 100%; height: 40px; margin-top: var(--space-3, 12px); }
.sparkline path { fill: none; stroke-width: 2; }
.sparkline .sl-line { stroke: var(--accent, #3ecf8e); }
.sparkline .sl-area,
.sl-area {
  fill: color-mix(in oklab, var(--accent, #3ecf8e) 8%, transparent);
  stroke: none;
}

/* \2500 \2500  Bar Chart \2500 \2500  */
.bar-chart {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 48px;
  margin-top: var(--space-3, 12px);
}
.bar-chart .bar {
  flex: 1;
  border-radius: 2px 2px 0 0;
  background: var(--accent, #3ecf8e);
  min-height: 4px;
  transition: height .6s var(--ease-standard, ease);
  opacity: .7;
}
.bar-chart .bar:first-child { opacity: 1; }

/* \2500 \2500  Donut \2500 \2500  */
.donut-wrap { display: flex; align-items: center; gap: var(--space-4, 16px); margin-top: var(--space-3, 12px); }
.donut { width: 72px; height: 72px; flex-shrink: 0; }
.donut circle { fill: none; stroke-width: 8; }
.donut .donut-track { stroke: var(--border, #2e2e2e); }
.donut .donut-fill {
  stroke: var(--accent, #3ecf8e);
  stroke-dasharray: 176;
  stroke-dashoffset: 176;
  stroke-linecap: round;
  transform: rotate(-90deg);
  transform-origin: 36px 36px;
}
.donut.animated .donut-fill { animation: donut-in 1.2s var(--ease-standard, ease) forwards; }
@keyframes donut-in { to { stroke-dashoffset: var(--offset, 0); } }

/* \2500 \2500  Activity Feed \2500 \2500  */
.activity { display: flex; flex-direction: column; gap: 0; }
.activity-item {
  display: flex;
  gap: var(--space-3, 12px);
  padding: var(--space-3, 12px) 0;
  position: relative;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .4s var(--ease-standard, ease), transform .4s var(--ease-standard, ease);
}
.activity-item.is-visible { opacity: 1; transform: translateY(0); }
.activity-item + .activity-item { border-top: 1px solid var(--border-soft, #242424); }
.ai-dot { width: 8px; height: 8px; border-radius: 50%; margin-top: 5px; flex-shrink: 0; }
.ai-dot.green { background: var(--success, #16a34a); }
.ai-dot.blue { background: var(--info, #2563eb); }
.ai-dot.yellow { background: var(--warn, #eab308); }
.ai-dot.red { background: var(--danger, #dc2626); }
.ai-dot.gray { background: var(--meta, #4d4d4d); }
.ai-dot.pulse { animation: pulse-dot 2s ease-in-out infinite; }
.ai-body { flex: 1; min-width: 0; }
.ai-body .ai-text { font-size: var(--text-sm, 14px); }
.ai-body .ai-text strong { font-weight: 500; }
.ai-body .ai-meta {
  font-size: var(--text-xs, 12px);
  color: var(--meta, #4d4d4d);
  margin-top: 2px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.ai-body .ai-meta .ai-tag {
  font-family: var(--font-mono, monospace);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: .06em;
  padding: 1px 6px;
  border-radius: var(--radius-pill, 9999px);
  background: var(--border-soft, #242424);
  color: var(--meta, #4d4d4d);
}
.ai-body .ai-meta .ai-tag.warn { background: color-mix(in oklab, var(--warn) 14%, transparent); color: var(--warn); }
.ai-body .ai-meta .ai-tag.ok { background: color-mix(in oklab, var(--success) 14%, transparent); color: var(--success); }
.ai-body .ai-meta .ai-tag.err { background: color-mix(in oklab, var(--danger) 14%, transparent); color: var(--danger); }

/* \2500 \2500  Progress \2500 \2500  */
.progress-group { display: flex; flex-direction: column; gap: var(--space-3, 12px); margin-top: var(--space-3, 12px); }
.progress-item { display: flex; flex-direction: column; gap: 4px; }
.progress-item .pi-label { display: flex; justify-content: space-between; font-size: var(--text-xs, 12px); color: var(--muted, #898989); }
.progress-item .pi-label strong { color: var(--fg, #fafafa); font-weight: 500; }
.progress-track { height: 4px; background: var(--border, #2e2e2e); border-radius: 2px; overflow: hidden; }
.progress-fill { height: 100%; border-radius: 2px; width: 0; transition: width 1.2s var(--ease-standard, ease); }
.progress-fill.accent { background: var(--accent, #3ecf8e); }
.progress-fill.success { background: var(--success, #16a34a); }
.progress-fill.warn,
.progress-fill.warning { background: var(--warn, #eab308); }
.progress-fill.danger { background: var(--danger, #dc2626); }
.progress-fill.indeterminate { width: 40%; animation: indeterminate 1.5s ease-in-out infinite; background: var(--accent); }
@keyframes indeterminate { 0% { transform: translateX(-100%); } 100% { transform: translateX(350%); } }

/* \2500 \2500  Circular Progress \2500 \2500  */
.circ-progress { width: 56px; height: 56px; position: relative; }
.circ-progress svg { transform: rotate(-90deg); }
.circ-progress .cp-track { fill: none; stroke: var(--border, #2e2e2e); stroke-width: 5; }
.circ-progress .cp-fill { fill: none; stroke: var(--accent, #3ecf8e); stroke-width: 5; stroke-linecap: round; stroke-dasharray: 138; stroke-dashoffset: 138; transition: stroke-dashoffset 1.2s var(--ease-standard, ease); }
.circ-progress .cp-label { position: absolute; inset: 0; display: grid; place-items: center; font-size: var(--text-sm, 14px); font-family: var(--font-mono, monospace); font-variant-numeric: tabular-nums; }
.ring-group { display: flex; gap: var(--space-5, 20px); margin-top: var(--space-3, 12px); }

/* \2500 \2500  Alerts \2500 \2500  */
.alert-list { display: flex; flex-direction: column; gap: var(--space-2, 8px); margin-top: var(--space-3, 12px); }
.alert-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3, 12px);
  padding: var(--space-3, 12px);
  border-radius: var(--radius-sm, 6px);
  font-size: var(--text-sm, 14px);
  animation: alert-in .35s var(--ease-standard, ease);
}
@keyframes alert-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
.alert-item.info { background: color-mix(in oklab, var(--info) 8%, var(--surface)); border-left: 3px solid var(--info); }
.alert-item.warn { background: color-mix(in oklab, var(--warn) 8%, var(--surface)); border-left: 3px solid var(--warn); }
.alert-item.success { background: color-mix(in oklab, var(--success) 8%, var(--surface)); border-left: 3px solid var(--success); }
.alert-item.danger { background: color-mix(in oklab, var(--danger) 8%, var(--surface)); border-left: 3px solid var(--danger); }
.alert-item .al-icon { flex-shrink: 0; margin-top: 1px; }
.alert-item .al-icon svg { width: 16px; height: 16px; }
.alert-item .al-body { flex: 1; }
.alert-item .al-body .al-title { font-weight: 500; margin-bottom: 2px; }
.alert-item .al-close { width: 20px; height: 20px; display: grid; place-items: center; background: none; border: none; cursor: pointer; color: var(--meta); border-radius: 4px; }
.alert-item .al-close:hover { background: var(--border-soft); color: var(--fg); }

/* \2500 \2500  Bento Grid \2500 \2500  */
.bento { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-3, 12px); margin-top: var(--space-3, 12px); }
.bento-cell { padding: var(--space-3, 12px); border: 1px solid var(--border, #2e2e2e); border-radius: var(--radius-sm, 6px); display: flex; flex-direction: column; gap: 2px; }
.bento-cell .bc-val { font-size: var(--text-xl, 24px); font-family: var(--font-mono, monospace); font-variant-numeric: tabular-nums; }
.bento-cell .bc-label { font-size: var(--text-xs, 12px); color: var(--muted, #898989); }
.bento-wide { grid-column: 1 / -1; }

/* \2500 \2500  Live Indicators \2500 \2500  */
.live-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: var(--radius-pill, 9999px);
  font-size: 10px;
  font-family: var(--font-mono, monospace);
  text-transform: uppercase;
  letter-spacing: .06em;
  background: color-mix(in oklab, var(--success) 12%, transparent);
  color: var(--success, #16a34a);
}
.live-pill .lp-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--success); animation: pulse-dot 2s ease-in-out infinite; }

/* \2500 \2500  Server Status \2500 \2500  */
.server-row { display: flex; align-items: center; gap: var(--space-3, 12px); padding: var(--space-2, 8px) 0; font-size: var(--text-sm, 14px); }
.server-row + .server-row { border-top: 1px solid var(--border-soft, #242424); }
.server-row .srv-name { flex: 1; }
.server-row .srv-status { display: flex; align-items: center; gap: 4px; font-size: var(--text-xs, 12px); font-family: var(--font-mono, monospace); }
.srv-status.up { color: var(--success); }
.srv-status.down { color: var(--danger); }
.srv-status.degraded { color: var(--warn); }
.srv-status .srv-dot { width: 6px; height: 6px; border-radius: 50%; }
.srv-status.up .srv-dot { background: var(--success); }
.srv-status.down .srv-dot { background: var(--danger); }
.srv-status.degraded .srv-dot { background: var(--warn); }
.srv-metrics { font-size: var(--text-xs, 12px); color: var(--meta, #4d4d4d); }
.srv-metrics .num { font-family: var(--font-mono, monospace); }

/* \2500 \2500  Notifications \2500 \2500  */
.notif-item { display: flex; align-items: flex-start; gap: var(--space-3, 12px); padding: var(--space-3, 12px) 0; border-bottom: 1px solid var(--border-soft, #242424); }
.notif-item:last-child { border-bottom: 0; }
.notif-icon { width: 28px; height: 28px; display: grid; place-items: center; border-radius: 50%; flex-shrink: 0; }
.notif-icon.info { background: color-mix(in oklab, var(--info) 14%, transparent); color: var(--info); }
.notif-icon.warn { background: color-mix(in oklab, var(--warn) 14%, transparent); color: var(--warn); }
.notif-icon.err { background: color-mix(in oklab, var(--danger) 14%, transparent); color: var(--danger); }
.notif-icon.ok { background: color-mix(in oklab, var(--success) 14%, transparent); color: var(--success); }
.notif-icon svg { width: 14px; height: 14px; }
.notif-body { flex: 1; min-width: 0; }
.notif-body .nf-text { font-size: var(--text-sm, 14px); }
.notif-body .nf-text strong { font-weight: 500; }
.notif-body .nf-time { font-size: var(--text-xs, 12px); color: var(--meta, #4d4d4d); margin-top: 1px; }

/* \2500 \2500  Usage Bars \2500 \2500  */
.usage-item { margin-bottom: var(--space-3, 12px); }
.usage-item:last-child { margin-bottom: 0; }
.usage-label { display: flex; justify-content: space-between; font-size: var(--text-xs, 12px); color: var(--muted, #898989); margin-bottom: 4px; }
.usage-label strong { color: var(--fg, #fafafa); font-weight: 500; }
.usage-track { height: 6px; background: var(--border, #2e2e2e); border-radius: 3px; overflow: hidden; }
.usage-fill { height: 100%; border-radius: 3px; width: 0; transition: width 1.4s var(--ease-standard, ease); }
.usage-fill.accent { background: var(--accent, #3ecf8e); }
.usage-fill.warn { background: var(--warn, #eab308); }
.usage-fill.danger { background: var(--danger, #dc2626); }

/* \2500 \2500 \2500  Card container (Datatable Supabase Theme) \2500 \2500 \2500 
   NOTE: .tb-card and .tb-card-head definitions have been moved to
   ttsc.financial-pages.css as the single source of truth.
   The original grid-based .l layout below is superseded by the flex layout
   that all 1,304+ pages expect. Keep .tb-card-body and table styles here
   since they serve the original widget context without conflict.
*/
/* .tb-card { border: 1px solid var(--border, #2e2e2e); border-radius: var(--radius-lg, 12px); background: var(--surface, #1c1c1c); overflow: hidden; } */
/* .tb-card-head { display: flex; align-items: center; justify-content: space-between; padding: var(--space-4, 16px) var(--space-5, 20px); border-bottom: 1px solid var(--border-soft, #242424); } */
/* .tb-card-head .l { display: grid; grid-template-columns: auto 1fr; ... } -- MOVED to ttsc.financial-pages.css */
/* .tb-card-head .l > i, .tb-card-head .l > svg { ... } -- MOVED */
/* .tb-card-head .l h3 { ... } -- MOVED */
/* .tb-card-head .l .meta { ... } -- MOVED */
/* .tb-card-head .l h3:last-child { ... } -- MOVED */
.tb-card-body { padding: var(--space-4, 16px) var(--space-5, 20px); }
.tb-card-body.no-pad { padding: 0; }

/* \2500 \2500 \2500  Table (widget-specific styles that augment financial-pages) \2500 \2500 \2500  */
.table-wrap { overflow-x: auto; -webkit-overflow-scrolling: touch; width: 100%; }
.tb-card table { width: 100%; border-collapse: collapse; font-size: 13px; }
.tb-card thead { background: var(--surface-2, #222222); border-bottom: 1px solid var(--border, #2e2e2e); }
.tb-card th { text-align: left; padding: 10px 14px; font-weight: 500; font-size: 11px; color: var(--muted, #898989); text-transform: uppercase; letter-spacing: .5px; white-space: nowrap; border-right: 1px solid var(--border-soft, #242424); user-select: none; cursor: default; }
.tb-card th:last-child { border-right: none; }
.tb-card th:hover { color: var(--fg-2, #b4b4b4); }
.tb-card td { padding: 10px 14px; border-bottom: 1px solid var(--border-soft, #242424); vertical-align: middle; color: var(--fg, #fafafa); white-space: nowrap; }
.tb-card tr:last-child td { border-bottom: none; }
.tb-card tr:hover td { background: var(--surface-2, #222222); }
.tb-card td .mono { font-family: var(--font-mono); font-size: 12px; color: var(--muted); }
.tb-card td .num { font-family: var(--font-mono); font-size: 12px; color: var(--fg-2); text-align: right; }
.tb-card td .cell-flex { display: flex; align-items: center; gap: 8px; }
.tb-card td .cell-flex .av { width: 26px; height: 26px; border-radius: var(--radius-sm, 6px); display: grid; place-items: center; font-size: 10px; font-weight: 600; flex-shrink: 0; }

/* \2500 \2500  Chart container \2500 \2500  */
.ttsc-chart { width: 100%; min-height: 180px; position: relative; }
.ttsc-chart-lg { min-height: 280px; }
.ttsc-chart-sm { min-height: 220px; }

/* \2500 \2500  Chart loading state \2500 \2500  */
.ttsc-chart .chart-loading { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%; min-height: inherit; gap: 10px; color: var(--muted-foreground, #6b7280); font-size: 13px; }
.ttsc-chart .chart-loading i { font-size: 32px; opacity: 0.5; }

/* Shared custom tooltip used by every Chart.js visualization in the app. */
.ttsc-chart-tooltip {
  position: absolute;
  z-index: 1200;
  width: max-content;
  max-width: min(18rem, calc(100vw - 1.5rem));
  pointer-events: none;
  border: 1px solid #334155;
  border-radius: .75rem;
  background: #0f172a;
  padding: .625rem .75rem;
  color: #e2e8f0;
  box-shadow: 0 12px 28px rgb(15 23 42 / .24);
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: .6875rem;
  line-height: 1.4;
}
.ttsc-chart-tooltip[hidden] { display: none; }
.ttsc-chart-tooltip-title { display: block; margin-bottom: .375rem; color: #f8fafc; font-weight: 700; }
.ttsc-chart-tooltip-row { display: flex; align-items: center; gap: .45rem; white-space: normal; }
.ttsc-chart-tooltip-swatch { width: .5rem; height: .5rem; flex: 0 0 .5rem; border-radius: 50%; }

/* \2500 \2500  Bento color classes \2500 \2500  */
.bc-val.accent { color: var(--accent, #3ecf8e); }
.bc-val.success { color: var(--success, #16a34a); }
.bc-val.danger { color: var(--danger, #dc2626); }
.bento-cell.is-current { border-color: var(--accent, #3ecf8e); background: color-mix(in oklab, var(--accent) 4%, var(--surface, #1c1c1c)); }

/* \2500 \2500  Button Group \2500 \2500  */
.btn-group { display: flex; gap: 0; margin-top: var(--space-3, 12px); }
.btn-group .bg-btn { padding: 5px 14px; border: 1px solid var(--border); background: transparent; font-size: var(--text-xs, 12px); color: var(--muted); transition: var(--motion-fast, 150ms) var(--ease-standard, ease); }
.btn-group .bg-btn:first-child { border-radius: 0.45rem 0 0 0.45rem; }
.btn-group .bg-btn:last-child { border-radius: 0 0.45rem 0.45rem 0; }
.btn-group .bg-btn + .bg-btn { border-left: 0; }
.btn-group .bg-btn:hover { background: var(--border-soft); color: var(--fg); }
.btn-group .bg-btn.is-active { background: color-mix(in oklab, var(--accent) 12%, transparent); border-color: var(--accent); color: var(--accent); }

/* \2500 \2500  Responsive \2500 \2500  */
@media (max-width: 1100px) {
  .widget { padding: var(--space-4, 16px); }
}
@media (max-width: 720px) {
  .widget { padding: var(--space-3, 12px); }
  .metric-value { font-size: var(--text-2xl, 32px); }
  .ring-group { flex-wrap: wrap; }
  .bento { grid-template-columns: 1fr; }
  .donut-wrap { flex-direction: column; align-items: flex-start; }
}

/* Custom Select Dropdown Pattern */
.select-wrap { position: relative; width: 100%; font-family: var(--font-body); }
.select-trigger { display: flex; align-items: center; justify-content: space-between; cursor: pointer; user-select: none; border: 1px solid var(--border); padding: 5px 10px; border-radius: var(--radius-md); background: var(--surface); color: var(--fg); font-size: 13px; min-height: 30px; transition: border-color 150ms, box-shadow 150ms; }
.select-trigger:hover { border-color: var(--border-strong); }
.select-trigger[aria-expanded="true"] { border-color: var(--ring); box-shadow: 0 0 0 1px var(--ring); outline: none; }
.select-trigger .value { flex: 1; text-align: left; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.select-trigger .caret { color: var(--muted); transition: transform 150ms; flex-shrink: 0; margin-left: 8px; }
.select-trigger[aria-expanded="true"] .caret { transform: rotate(180deg); color: var(--fg); }
.select-wrap .menu { position: absolute; top: calc(100% + 4px); left: 0; right: 0; background: var(--surface-2); border: 1px solid var(--border); border-radius: var(--radius-md); padding: 4px; box-shadow: var(--elev-raised); z-index: 10000; opacity: 0; transform: translateY(-4px); pointer-events: none; transition: opacity 150ms, transform 150ms; max-height: 240px; overflow-y: auto; }
.select-wrap .menu.is-open { opacity: 1; transform: translateY(0); pointer-events: auto; }
.select-wrap .menu .item { display: flex; align-items: center; gap: 8px; padding: 6px 8px; border-radius: var(--radius-sm); font-size: 13px; color: var(--fg-2); cursor: pointer; user-select: none; }
.select-wrap .menu .item:hover { background: var(--surface); color: var(--fg); }
.select-wrap .menu .item.is-selected { color: var(--fg); }
.select-wrap .menu .item.is-selected::after { content: ""; margin-left: auto; width: 14px; height: 14px; background: var(--accent); -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='3' stroke-linecap='round' stroke-linejoin='round'><polyline points='20 6 9 17 4 12'/></svg>") center/contain no-repeat; mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='3' stroke-linecap='round' stroke-linejoin='round'><polyline points='20 6 9 17 4 12'/></svg>") center/contain no-repeat; }
/* -- Pagination (Supabase Pattern) -- */
.pagination {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--space-3, 12px) var(--space-5, 20px);
    border-top: 1px solid var(--border-soft, #242424);
    flex-wrap: wrap;
    gap: 8px;
}
.pagination .info {
    font-size: 12px;
    color: var(--muted, #898989);
}
.pagination .info strong, .pagination .info span {
    color: var(--fg, #fafafa);
    font-weight: 500;
}
.pagination .pages {
    display: flex;
    align-items: center;
    gap: 2px;
}
.pagination .pages .page { width: 32px; height: 32px; display: grid; place-items: center; border-radius: 6px; font-size: 12px; font-weight: bold; color: var(--fg, #fafafa); cursor: pointer; transition: 150ms; border: 1px solid var(--border, #2e2e2e); background: var(--surface, #1c1c1c); }
.pagination .pages .page:hover:not([disabled]) { background: var(--surface-2, #222222); }
.pagination .pages .page.is-active { background: var(--accent, #3ecf8e); border-color: var(--accent, #3ecf8e); color: #fff; }
.pagination .pages .page.dots {
    color: var(--meta, #4d4d4d);
    cursor: default;
}
.pagination .pages .page.dots:hover {
    border-color: transparent;
    background: none;
}
.pagination .pages .page[disabled] {
    opacity: 0.5;
    cursor: not-allowed;
}

.pagination .per-page {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 8px;
    font-size: 12px;
    color: var(--muted, #898989);
    white-space: nowrap;
    flex-wrap: nowrap;
}
/* Fix custom select width inside pagination */
.pagination .per-page .select-wrap {
    width: auto !important;
    min-width: 60px;
    display: inline-block;
    flex: 0 0 auto;
}
.pagination .per-page span { 
    width: auto !important; 
    flex: 0 0 auto;
}

/* ===== assets/css/ttsc.kpi-widgets.css ===== */
/* \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 
   TTSC MODERN KPI & DASHBOARD WIDGETS DESIGN SYSTEM
   High-end, data-dense widget components (Light & Dark Mode)
   \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550  */

:root {
  --kpi-purple: #8b5cf6;
  --kpi-purple-soft: rgba(139, 92, 246, 0.12);
  --kpi-blue: #3b82f6;
  --kpi-blue-soft: rgba(59, 130, 246, 0.12);
  --kpi-cyan: #06b6d4;
  --kpi-cyan-soft: rgba(6, 182, 212, 0.12);
  --kpi-teal: #10b981;
  --kpi-teal-soft: rgba(16, 185, 129, 0.12);
  --kpi-yellow: #f59e0b;
  --kpi-yellow-soft: rgba(245, 158, 11, 0.12);
  --kpi-orange: #f97316;
  --kpi-orange-soft: rgba(249, 115, 22, 0.12);
  --kpi-card-bg: var(--surface, #ffffff);
  --kpi-card-border: var(--border, #e5e7eb);
  --kpi-card-radius: 16px;
  --kpi-card-shadow: 0 1px 3px rgba(0, 0, 0, 0.04), 0 1px 2px rgba(0, 0, 0, 0.02);
}

[data-theme="dark"] {
  --kpi-card-bg: var(--surface, #18181b);
  --kpi-card-border: var(--border, #27272a);
  --kpi-card-shadow: 0 4px 12px rgba(0, 0, 0, 0.3);
}

/* \2500 \2500 \2500  Grid Systems \2500 \2500 \2500  */
.kpi-grid-top {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
  margin-bottom: 1.25rem;
}

.kpi-grid-bottom {
  display: grid;
  grid-template-columns: 1fr 1.6fr;
  gap: 1.25rem;
  margin-bottom: 1.25rem;
}

@media (max-width: 1200px) {
  .kpi-grid-top {
    grid-template-columns: repeat(2, 1fr);
  }
  .kpi-grid-bottom {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .kpi-grid-top {
    grid-template-columns: 1fr;
  }
}

/* \2500 \2500 \2500  Base Widget Card \2500 \2500 \2500  */
.kpi-widget-card {
  background: var(--kpi-card-bg);
  border: 1px solid var(--kpi-card-border);
  border-radius: var(--kpi-card-radius);
  padding: 1.25rem 1.5rem;
  box-shadow: var(--kpi-card-shadow);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  position: relative;
  transition: all 0.2s ease;
}

.kpi-widget-card:hover {
  border-color: color-mix(in oklab, var(--kpi-card-border) 70%, var(--accent, #3ecf8e));
}

.kpi-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}

.kpi-card-head h4 {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--fg, #18181b);
  margin: 0;
  letter-spacing: -0.01em;
}

.kpi-head-action {
  color: var(--muted, #9ca3af);
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px 6px;
  border-radius: 6px;
  font-size: 14px;
  transition: color 0.15s ease;
}

.kpi-head-action:hover {
  color: var(--fg, #18181b);
}

.kpi-head-link {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--muted, #6b7280);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: color 0.15s ease;
}

.kpi-head-link:hover {
  color: var(--accent, #3ecf8e);
}

/* \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 
   CARD 1: SEGMENTED COUNTER (Ex: Total Employees / Students)
   \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550  */
.kpi-counter-rows {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.kpi-counter-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.625rem 0.875rem;
  border-radius: 10px;
  background: var(--surface-2, rgba(0, 0, 0, 0.02));
  border: 1px solid var(--border-soft, rgba(0, 0, 0, 0.04));
  transition: background 0.15s ease;
}

.kpi-counter-row.is-green {
  background: var(--kpi-teal-soft);
  border-color: rgba(16, 185, 129, 0.15);
}

.kpi-counter-row.is-yellow {
  background: var(--kpi-yellow-soft);
  border-color: rgba(245, 158, 11, 0.15);
}

.kpi-counter-row.is-blue {
  background: var(--kpi-blue-soft);
  border-color: rgba(59, 130, 246, 0.15);
}

.kpi-counter-left {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
}

.kpi-counter-num {
  font-size: 1.5rem;
  font-weight: 700;
  font-family: var(--font-display, inherit);
  color: var(--fg, #111827);
  line-height: 1;
}

.kpi-delta-tag {
  font-size: 0.75rem;
  font-weight: 700;
  font-family: var(--font-mono, monospace);
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.kpi-delta-tag.up {
  color: #10b981;
}

.kpi-delta-tag.down {
  color: #f59e0b;
}

.kpi-counter-label {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--fg, #374151);
}

.is-green .kpi-counter-label {
  color: #065f46;
}
[data-theme="dark"] .is-green .kpi-counter-label {
  color: #34d399;
}

.is-yellow .kpi-counter-label {
  color: #92400e;
}
[data-theme="dark"] .is-yellow .kpi-counter-label {
  color: #fbbf24;
}

/* \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 
   CARD 2: PERCENTAGE OVERVIEW (Ex: Attendance Overview)
   \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550  */
.kpi-metric-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 0.875rem;
}

.kpi-big-percent {
  font-size: 2rem;
  font-weight: 800;
  font-family: var(--font-display, inherit);
  color: var(--fg, #111827);
  line-height: 1;
}

.kpi-badge-trend {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 0.75rem;
  font-weight: 600;
  color: #10b981;
  background: var(--kpi-teal-soft);
  padding: 3px 8px;
  border-radius: 9999px;
}

.kpi-badge-trend .trend-sub {
  color: var(--muted, #6b7280);
  font-weight: 500;
}

.kpi-segmented-bar {
  display: flex;
  height: 8px;
  border-radius: 9999px;
  overflow: hidden;
  gap: 3px;
  margin-bottom: 1rem;
  background: var(--border-soft, #f3f4f6);
}

.kpi-bar-seg {
  height: 100%;
  border-radius: 4px;
  transition: width 0.4s ease;
}

.kpi-legend-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
  font-size: 0.75rem;
  color: var(--muted, #6b7280);
}

.kpi-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 500;
}

.kpi-legend-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

/* \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 
   CARD 3: SEMI-CIRCLE GAUGE & BREAKDOWN (Ex: Used Devices)
   \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550  */
.kpi-gauge-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
}

.kpi-gauge-visual {
  position: relative;
  width: 140px;
  height: 75px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  flex-shrink: 0;
}

.kpi-gauge-svg {
  width: 140px;
  height: 75px;
  overflow: visible;
}

.kpi-gauge-center {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
}

.kpi-gauge-num {
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--fg, #111827);
  line-height: 1;
  display: block;
}

.kpi-gauge-lbl {
  font-size: 0.6875rem;
  color: var(--muted, #6b7280);
  font-weight: 500;
  display: block;
  margin-top: 2px;
}

.kpi-gauge-breakdown {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  flex: 1;
}

.kpi-breakdown-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
}

.kpi-breakdown-left {
  display: flex;
  align-items: center;
  gap: 6px;
}

.kpi-pill-bar {
  width: 3.5px;
  height: 14px;
  border-radius: 2px;
  flex-shrink: 0;
}

.kpi-breakdown-val {
  font-family: var(--font-mono, monospace);
  font-weight: 700;
  color: var(--fg, #111827);
}

.kpi-breakdown-lbl {
  color: var(--muted, #6b7280);
  font-weight: 500;
}

/* \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 
   CARD 4: PERFORMANCE RATINGS (Ex: Employee Performance)
   \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550  */
.kpi-perf-header-score {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.kpi-perf-score {
  font-size: 2.25rem;
  font-weight: 800;
  font-family: var(--font-display, inherit);
  color: var(--fg, #111827);
  line-height: 1;
  flex-shrink: 0;
}

.kpi-perf-note {
  font-size: 0.75rem;
  color: var(--muted, #6b7280);
  line-height: 1.4;
  margin: 0;
}

.kpi-perf-list {
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
  margin-bottom: 1rem;
}

.kpi-perf-item {
  display: grid;
  grid-template-columns: 110px 1fr;
  align-items: center;
  gap: 0.875rem;
}

.kpi-perf-name {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--fg, #374151);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.kpi-perf-bar-track {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
}

.kpi-perf-bar-seg {
  height: 14px;
  border-radius: 9999px;
  transition: width 0.3s ease;
}

.kpi-perf-scale {
  display: flex;
  justify-content: space-between;
  margin-left: 110px;
  padding-left: 0.875rem;
  font-size: 0.6875rem;
  font-family: var(--font-mono, monospace);
  color: var(--muted, #9ca3af);
  margin-bottom: 0.875rem;
}

/* \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 
   CARD 5: DUAL-LAYER STRIPED BAR CHART (Ex: Income Statistics)
   \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550  */
.kpi-chart-container {
  display: flex;
  gap: 0.75rem;
  height: 220px;
  margin-top: 0.5rem;
  position: relative;
}

.kpi-y-axis {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-size: 0.6875rem;
  font-family: var(--font-mono, monospace);
  color: var(--muted, #9ca3af);
  text-align: right;
  padding-bottom: 24px;
  user-select: none;
}

.kpi-chart-plot {
  flex: 1;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px;
  border-bottom: 1px solid var(--border-soft, #e5e7eb);
  padding-bottom: 0;
  position: relative;
}

.kpi-plot-col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
  justify-content: flex-end;
  position: relative;
  cursor: pointer;
}

.kpi-col-bars {
  width: 100%;
  max-width: 32px;
  display: flex;
  flex-direction: column-reverse;
  border-radius: 8px;
  overflow: hidden;
  background: var(--surface-2, rgba(0, 0, 0, 0.03));
  position: relative;
  transition: transform 0.15s ease;
}

.kpi-plot-col:hover .kpi-col-bars,
.kpi-plot-col.is-active .kpi-col-bars {
  transform: scaleY(1.02);
}

.kpi-bar-solid {
  width: 100%;
  background: var(--kpi-purple);
  border-radius: 0 0 6px 6px;
  transition: height 0.4s ease;
}

.kpi-bar-striped {
  width: 100%;
  background: repeating-linear-gradient(
    45deg,
    #3b82f6,
    #3b82f6 4px,
    #60a5fa 4px,
    #60a5fa 8px
  );
  border-radius: 6px 6px 0 0;
  transition: height 0.4s ease;
}

.kpi-col-label {
  font-size: 0.6875rem;
  color: var(--muted, #9ca3af);
  margin-top: 8px;
  font-weight: 500;
  text-align: center;
  transition: color 0.15s ease;
}

.kpi-plot-col.is-active .kpi-col-label {
  color: var(--fg, #111827);
  font-weight: 700;
}

.kpi-col-dot {
  position: absolute;
  top: -12px;
  width: 6px;
  height: 6px;
  background: var(--kpi-purple);
  border-radius: 50%;
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.2);
}

/* \2500 \2500  Interactive Floating Tooltip \2500 \2500  */
.kpi-chart-tooltip {
  position: absolute;
  top: -5px;
  right: auto;
  transform: translateX(-50%);
  width: 165px;
  min-width: 165px;
  max-width: 165px;
  box-sizing: border-box;
  background: var(--kpi-card-bg);
  border: 1px solid var(--kpi-card-border);
  border-radius: 10px;
  padding: 0.5rem 0.75rem;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.15), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  z-index: 20;
  pointer-events: none;
  transition: left 0.25s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.2s ease;
}

.kpi-tooltip-title {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--fg, #111827);
  margin-bottom: 0.5rem;
}

.kpi-tooltip-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.75rem;
  margin-bottom: 3px;
}

.kpi-tooltip-row:last-child {
  margin-bottom: 0;
}

.kpi-tooltip-lbl {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--muted, #6b7280);
}

.kpi-tooltip-val {
  font-weight: 700;
  color: var(--fg, #111827);
  font-family: var(--font-mono, monospace);
}

/* ===== assets/css/ttsc.notifications.css ===== */
/* 
 * TTSC Premium Notification System 
 * Design: totustuussoftcloud V2 / Modern Glassmorphism
 */

#toast-container,
#ttsc-notification-container {
    position: fixed;
    top: 1.5rem;
    right: 1.5rem;
    z-index: 9999;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    pointer-events: none;
    max-width: min(400px, calc(100vw - 2rem));
    width: 100%;
}

.ttsc-notification {
    pointer-events: auto;
    background: rgba(var(--ttsc-background-rgb), 0.85);
    backdrop-filter: blur(12px) saturate(180%);
    -webkit-backdrop-filter: blur(12px) saturate(180%);
    border: 1px solid rgba(var(--ttsc-border-rgb), 0.5);
    border-radius: 1rem;
    padding: 1rem;
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
    display: flex;
    align-items: flex-start;
    gap: 0.875rem;
    transform: translateX(120%);
    transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1);
    opacity: 0;
    position: relative;
    overflow: hidden;
}

.ttsc-notification.show {
    transform: translateX(0);
    opacity: 1;
}

.ttsc-notification.hide {
    transform: translateX(120%);
    opacity: 0;
    margin-top: -4.5rem; /* Collapse space */
}

.ttsc-notification-icon {
    flex-shrink: 0;
    width: 2.25rem;
    height: 2.25rem;
    border-radius: 0.75rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1rem;
}

.ttsc-notification-content {
    flex-grow: 1;
    display: flex;
    flex-direction: column;
    gap: 0.125rem;
}

.ttsc-notification-title {
    font-size: 0.875rem;
    font-weight: 700;
    color: var(--ttsc-foreground);
    line-height: 1.25rem;
}

.ttsc-notification-message {
    font-size: 0.8125rem;
    color: var(--ttsc-muted-foreground);
    line-height: 1.125rem;
}

.ttsc-notification-close {
    flex-shrink: 0;
    color: var(--ttsc-muted-foreground);
    opacity: 0.5;
    transition: opacity 0.2s;
    cursor: pointer;
    padding: 0.25rem;
    margin: -0.25rem;
}

.ttsc-notification-close:hover {
    opacity: 1;
}

/* Success State */
.ttsc-notification-success .ttsc-notification-icon {
    background: rgba(16, 185, 129, 0.15);
    color: var(--success, #10b981);
}
.ttsc-notification-success {
    border-left: 4px solid var(--success, #10b981);
}

/* Error State */
.ttsc-notification-error .ttsc-notification-icon {
    background: rgba(239, 68, 68, 0.15);
    color: var(--danger, #ef4444);
}
.ttsc-notification-error {
    border-left: 4px solid var(--danger, #ef4444);
}

/* Destructive State (Solid Red) */
.ttsc-notification-destructive {
    background: var(--danger, #ef4444) !important;
    border: none !important;
}
.ttsc-notification-destructive .ttsc-notification-title,
.ttsc-notification-destructive .ttsc-notification-message,
.ttsc-notification-destructive .ttsc-notification-close,
.ttsc-notification-destructive .ttsc-notification-icon {
    color: white !important;
}
.ttsc-notification-destructive .ttsc-notification-icon {
    background: rgba(255, 255, 255, 0.2) !important;
}
.ttsc-notification-destructive .ttsc-notification-progress {
    background: white !important;
}

/* Warning State */
.ttsc-notification-warning .ttsc-notification-icon {
    background: rgba(245, 158, 11, 0.15);
    color: var(--warn, #f59e0b);
}
.ttsc-notification-warning {
    border-left: 4px solid var(--warn, #f59e0b);
}

/* Info State */
.ttsc-notification-info .ttsc-notification-icon {
    background: rgba(59, 130, 246, 0.15);
    color: var(--info, #3b82f6);
}
.ttsc-notification-info {
    border-left: 4px solid var(--info, #3b82f6);
}

/* Progress bar for auto-hide */
.ttsc-notification-progress {
    position: absolute;
    bottom: 0;
    left: 0;
    height: 3px;
    background: currentColor;
    opacity: 0.3;
    width: 100%;
    transform-origin: left;
}

@keyframes ttsc-notification-progress-anim {
    from { transform: scaleX(1); }
    to { transform: scaleX(0); }
}

/* \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 
   NOTIFICATION CENTER \2014  In-App Drawer
   \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550  */

.notif-center-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.3);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: 9998;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s ease;
}

.notif-center-backdrop.open {
    opacity: 1;
    pointer-events: auto;
}

.notif-center-drawer {
    position: fixed;
    top: 0;
    right: 0;
    width: min(420px, 100vw);
    height: 100vh;
    height: 100dvh;
    background: var(--ttsc-background, #fff);
    border-left: 1px solid var(--ttsc-border, #e5e7eb);
    box-shadow: none;
    z-index: 9999;
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.notif-center-drawer.open {
    transform: translateX(0);
    box-shadow: -8px 0 30px rgba(0, 0, 0, 0.12);
}

html.dark .notif-center-drawer.open {
    box-shadow: -8px 0 30px rgba(0, 0, 0, 0.4);
}

/* \2500 \2500 \2500  Header \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500  */

.notif-center-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 1.25rem;
    border-bottom: 1px solid var(--ttsc-border, #e5e7eb);
    flex-shrink: 0;
}

.notif-center-header-left {
    display: flex;
    align-items: center;
    gap: 0.625rem;
}

.notif-center-title {
    font-size: 1rem;
    font-weight: 700;
    color: var(--ttsc-foreground, #111827);
    margin: 0;
    line-height: 1.3;
}

.notif-center-count-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.375rem;
    height: 1.375rem;
    padding: 0 0.375rem;
    background: var(--danger, #ef4444);
    color: #fff;
    font-size: 0.6875rem;
    font-weight: 700;
    border-radius: 999px;
    line-height: 1;
}

.notif-center-header-right {
    display: flex;
    align-items: center;
    gap: 0.25rem;
}

.notif-center-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border: none;
    border-radius: 0.5rem;
    background: transparent;
    color: var(--ttsc-muted-foreground, #6b7280);
    cursor: pointer;
    transition: all 0.2s ease;
    gap: 0.375rem;
}

.notif-center-btn:hover {
    background: var(--ttsc-muted, #f3f4f6);
    color: var(--ttsc-foreground, #111827);
}

.notif-center-btn-ghost:hover {
    background: var(--ttsc-muted, #f3f4f6);
}

.notif-center-btn-label {
    font-size: 0.75rem;
    font-weight: 500;
    white-space: nowrap;
}

@media (max-width: 480px) {
    .notif-center-btn-label {
        display: none;
    }
}

/* \2500 \2500 \2500  Tabs \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500  */

.notif-center-tabs {
    display: flex;
    gap: 0.25rem;
    padding: 0.75rem 1.25rem 0;
    border-bottom: 1px solid var(--ttsc-border, #e5e7eb);
    flex-shrink: 0;
}

.notif-center-tab {
    padding: 0.5rem 0.875rem;
    font-size: 0.8125rem;
    font-weight: 500;
    color: var(--ttsc-muted-foreground, #6b7280);
    background: transparent;
    border: none;
    border-bottom: 2px solid transparent;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-bottom: -1px;
    border-radius: 0.375rem 0.375rem 0 0;
}

.notif-center-tab:hover {
    color: var(--ttsc-foreground, #111827);
    background: var(--ttsc-muted, #f3f4f6);
}

.notif-center-tab.is-active {
    color: var(--accent, #6366f1);
    border-bottom-color: var(--accent, #6366f1);
    font-weight: 600;
}

/* \2500 \2500 \2500  List Container \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500  */

.notif-center-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
    overscroll-behavior: contain;
}

.notif-center-list::-webkit-scrollbar {
    width: 4px;
}

.notif-center-list::-webkit-scrollbar-track {
    background: transparent;
}

.notif-center-list::-webkit-scrollbar-thumb {
    background: var(--ttsc-border, #e5e7eb);
    border-radius: 2px;
}

/* \2500 \2500 \2500  Loading & Empty States \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500  */

.notif-center-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 3rem 1.5rem;
    text-align: center;
}

.notif-center-spinner {
    width: 2rem;
    height: 2rem;
    border: 2.5px solid var(--ttsc-border, #e5e7eb);
    border-top-color: var(--accent, #6366f1);
    border-radius: 50%;
    animation: notif-spin 0.8s linear infinite;
    margin-bottom: 0.75rem;
}

@keyframes notif-spin {
    to { transform: rotate(360deg); }
}

.notif-center-state-text {
    font-size: 0.8125rem;
    color: var(--ttsc-muted-foreground, #6b7280);
    margin: 0;
}

/* \2500 \2500 \2500  Notification Items \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500  */

.notif-item {
    display: flex;
    align-items: flex-start;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    transition: background 0.15s ease;
    position: relative;
    border-left: 3px solid transparent;
}

.notif-item:hover {
    background: var(--ttsc-muted, #f3f4f6);
}

.notif-item.is-unread {
    background: rgba(var(--ttsc-accent-rgb, 99, 102, 241), 0.04);
    border-left-color: var(--accent, #6366f1);
}

.notif-item.is-unread:hover {
    background: rgba(var(--ttsc-accent-rgb, 99, 102, 241), 0.08);
}

.notif-item-icon {
    flex-shrink: 0;
    margin-top: 0.125rem;
}

.notif-item-body {
    flex: 1;
    min-width: 0;
}

.notif-item-title {
    font-size: 0.8125rem;
    font-weight: 600;
    color: var(--ttsc-foreground, #111827);
    line-height: 1.35;
    display: flex;
    align-items: center;
    gap: 0.375rem;
    margin-bottom: 0.125rem;
}

.notif-item.is-read .notif-item-title {
    font-weight: 500;
}

.notif-dot {
    display: inline-block;
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 50%;
    background: var(--accent, #6366f1);
    flex-shrink: 0;
    animation: notif-dot-pulse 2s ease-in-out infinite;
}

@keyframes notif-dot-pulse {
