}

/* ===== assets/css/ttsc.drawer.css ===== */
/* \2500 \2500 \2500  sb-drawer \2014  Supabase-themed Drawer Container \2500 \2500 \2500  */
/* Extracted from resources/views/app/components/sb-drawer.php         */
/* for global availability across all pages that use inline drawers.   */

/* \2500 \2500 \2500  Drawer Backdrop \2500 \2500 \2500  */
.sb-drawer-backdrop,
.drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1040;
  background: rgba(0, 0, 0, 0.5);
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
  transition: opacity 0.2s cubic-bezier(0.16, 1, 0.3, 1), visibility 0.2s;
  will-change: opacity;
}

@supports (backdrop-filter: blur(2px)) or (-webkit-backdrop-filter: blur(2px)) {
  .sb-drawer-backdrop.is-open,
  .sb-drawer-backdrop.open,
  .sb-drawer-backdrop.active,
  .drawer-backdrop.is-open,
  .drawer-backdrop.open,
  .drawer-backdrop.active {
    backdrop-filter: blur(2px);
    -webkit-backdrop-filter: blur(2px);
  }
}

.sb-drawer-backdrop.is-open,
.sb-drawer-backdrop.open,
.sb-drawer-backdrop.active,
.drawer-backdrop.is-open,
.drawer-backdrop.open,
.drawer-backdrop.active {
  opacity: 1 !important;
  pointer-events: auto !important;
  visibility: visible !important;
}

/* \2500 \2500 \2500  Drawer Panel \2500 \2500 \2500  */
.sb-drawer,
.drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 1050;
  width: var(--drawer-width, min(640px, 92vw));
  max-width: 100vw;
  background: var(--sb-surface, #ffffff);
  border-left: 1px solid var(--sb-border, #e5e7eb);
  border-left-color: transparent;
  transform: translateX(100%);
  visibility: hidden;
  pointer-events: none;
  transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1),
              visibility 0.25s step-end,
              box-shadow 0.25s ease;
  display: flex;
  flex-direction: column;
  box-shadow: none;
  padding: 2px;
  box-sizing: border-box;
}

.sb-drawer.is-open,
.sb-drawer.open,
.sb-drawer.active,
.drawer.is-open,
.drawer.open,
.drawer.active {
  transform: translateX(0) !important;
  visibility: visible !important;
  pointer-events: auto !important;
  transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1),
              visibility 0.25s step-start,
              box-shadow 0.25s ease;
  border-left-color: var(--sb-border, #e5e7eb) !important;
  box-shadow: -4px 0 24px rgba(0, 0, 0, 0.1) !important;
}

/* \2500 \2500 \2500  DARK MODE DRAWER COMPREHENSIVE FIX (#14171c, #1a1d24, #242832) \2500 \2500 \2500  */
