/* \2500 \2500 \2500  Supabase Select Box Styles (.sb-select-container) \2500 \2500 \2500  */
.sb-select-container {
  position: relative;
  width: 100%;
}

.sb-select-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background: var(--surface, #ffffff);
  border: 1px solid var(--border, #e5e7eb);
  border-radius: 8px;
  font-size: 13px;
  color: var(--fg, #0f172a);
  cursor: pointer;
  transition: all 0.15s ease;
}

.sb-select-trigger:hover {
  border-color: var(--accent, #10b981);
}

.sb-select-container.is-open .sb-select-trigger {
  border-color: var(--accent, #10b981);
  box-shadow: 0 0 0 2px rgba(16, 185, 129, 0.15);
}

.sb-select-menu {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  background: var(--surface, #ffffff);
  border: 1px solid var(--border, #e5e7eb);
  border-radius: 8px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
  z-index: 9999;
  display: none;
  max-height: 220px;
  overflow-y: auto;
  padding: 4px;
}

.sb-select-container.is-open .sb-select-menu {
  display: block !important;
}

.sb-select-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  font-size: 13px;
  color: var(--fg, #0f172a);
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.12s ease;
}

.sb-select-option:hover {
  background: var(--bg-2, #f8f9fa);
}

.sb-select-option.is-selected {
  background: rgba(16, 185, 129, 0.08);
  font-weight: 600;
  color: var(--accent, #10b981);
}

/* \2500 \2500 \2500  Segmented Control Tab Bar (Apple / Supabase Style) \2500 \2500 \2500  */
.ud-tab-segmented {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 3px;
  background: var(--bg-2, #f1f5f9);
  border: 1px solid var(--border-soft, #e2e8f0);
  border-radius: 10px;
  width: 100%;
  box-sizing: border-box;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none; /* IE 10+ */
}

.ud-tab-segmented::-webkit-scrollbar {
  display: none; /* Chrome/Safari */
}

.ud-tab-segmented .ud-tab-btn {
  flex: 1 1 0%;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 6px 6px;
  border-radius: 7px;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--muted, #64748b);
  background: transparent;
  border: 1px solid transparent;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s cubic-bezier(0.16, 1, 0.3, 1);
  box-sizing: border-box;
}

.ud-tab-segmented .ud-tab-btn span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ud-tab-segmented .ud-tab-btn:hover {
  color: var(--fg, #0f172a);
}

.ud-tab-segmented .ud-tab-btn.active {
  background: var(--surface, #ffffff) !important;
  color: var(--fg, #0f172a) !important;
  font-weight: 600 !important;
  border-color: rgba(0, 0, 0, 0.06) !important;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08), 0 1px 2px rgba(0, 0, 0, 0.04) !important;
}

.ud-tab-badge {
  font-size: 9.5px;
  font-weight: 600;
  padding: 1px 5px;
  border-radius: 9999px;
  background: rgba(148, 163, 184, 0.2);
