  transition: all 0.15s ease;
  line-height: 1.2;
  flex-shrink: 0;
}

.ud-tab-segmented .ud-tab-btn.active .ud-tab-badge {
  background: var(--accent, #10b981);
  color: #ffffff;
}

.dark .ud-tab-segmented {
  background: #111827;
  border-color: #1f2937;
}

.dark .ud-tab-segmented .ud-tab-btn.active {
  background: #1f2937 !important;
  color: #f9fafb !important;
  border-color: #374151 !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3) !important;
}

/* \2500 \2500 \2500  User Drawer Cards (Homogeneous Dark Mode & Light Mode) \2500 \2500 \2500  */
.ud-card {
  background: var(--surface-raised, #f8f9fa);
  border: 1px solid var(--border-soft, #ebebeb);
  border-radius: 10px;
  padding: 14px;
  transition: background 150ms ease, border-color 150ms ease;
}

.dark .ud-card {
  background: #18181b !important;
  border-color: #27272a !important;
  color: #f4f4f5 !important;
}

.dark .ud-card label {
  color: #a1a1aa !important;
}

.dark .ud-card .sb-select-trigger,
.dark .ud-card input,
.dark .ud-card select {
  background: #121214 !important;
  border-color: #27272a !important;
  color: #f4f4f5 !important;
}

/* Homogeneous theme option buttons */
.ttsc-theme-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 500;
  padding: 8px 10px;
  border-radius: 7px;
  border: 1px solid var(--border, #e4e4e7);
  background: var(--surface, #ffffff);
  color: var(--fg, #18181b);
  cursor: pointer;
  transition: all 150ms ease;
}

.ttsc-theme-btn i {
  color: var(--accent, #10b981);
  font-size: 13px;
}

.ttsc-theme-btn:hover {
  border-color: var(--accent, #10b981);
  background: var(--accent-soft, rgba(16, 185, 129, 0.06));
}

.dark .ttsc-theme-btn {
  background: #121214;
  border-color: #27272a;
  color: #f4f4f5;
}

.dark .ttsc-theme-btn:hover {
  border-color: var(--accent, #10b981);
  background: rgba(16, 185, 129, 0.12);
}

/* \2500 \2500 \2500  PII / LGPD Drawer Priority Stacking (Stacks Above All Other Drawers) \2500 \2500 \2500  */
#piiDrawerBackdrop,
.sb-drawer-backdrop#piiDrawerBackdrop {
  z-index: 1190 !important;
}

#piiDrawer,
.sb-drawer#piiDrawer {
  z-index: 1200 !important;
}

/* Dynamic PII Reveal Drawer (created by ttsc.pii-reveal.js) */
#piiRevealDrawerBackdrop,
.sb-drawer-backdrop#piiRevealDrawerBackdrop {
  z-index: 1190 !important;
}

#piiRevealDrawer,
.sb-drawer#piiRevealDrawer {
  z-index: 1200 !important;
}

/* \2500 \2500 \2500  Drawer Dropdown Menus Safeguards \2500 \2500 \2500  */
.drawer-panel [class*="dropdown"],
.drawer-panel [id*="dropdown"],
.drawer-panel .ttsc-select-dropdown,
.sb-drawer [class*="dropdown"],
.sb-drawer [id*="dropdown"],
.sb-drawer .ttsc-select-dropdown,
#notif-options-dropdown,
#search-tabs-overflow-dropdown {
  max-width: none !important;
  box-sizing: border-box !important;
}
#notif-options-dropdown {
  min-width: 240px !important;
  width: 15rem !important;
  right: 0 !important;
}
#search-tabs-overflow-dropdown {
  min-width: 224px !important;
  width: 14rem !important;
  right: 0 !important;
}

/* \2500 \2500 \2500  Drawer width: single source of truth \2500 \2500 \2500 
   Every drawer panel reads its width from one custom property instead of
   competing `!important` width rules. Default lives on :root (lowest
   specificity) so the `.w-[460px]` \2026  `.w-[620px]` utility classes can
   override it per drawer, while drawers without a width class still get a
   sane 480px panel instead of shrink-to-fit. `max-width: 100%` below keeps
   small viewports fluid. */
:root {
  --ttsc-drawer-width: 480px;
}

/* \2500 \2500 \2500  Universal .drawer-panel Sliding Transforms \2500 \2500 \2500  */
.drawer-panel {
  position: fixed !important;
  top: 0 !important;
  right: 0 !important;
  height: 100% !important;
  width: var(--ttsc-drawer-width, 480px) !important;
  transform: translateX(100%) !important;
  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.25s ease, visibility 0.25s !important;
  box-shadow: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
  z-index: 50 !important;
  max-width: 100% !important;
}

.drawer-panel.open,
.drawer-panel.is-open,
.drawer-panel.active {
  transform: translateX(0) !important;
  visibility: visible !important;
  opacity: 1 !important;
  pointer-events: auto !important;
  box-shadow: -10px 0 30px -5px rgba(0, 0, 0, 0.18), -4px 0 12px -2px rgba(0, 0, 0, 0.08) !important;
}

#backdrop-overlay {
  transition: opacity 0.3s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.3s ease;
}

#backdrop-overlay.open,
#backdrop-overlay.is-open,
#backdrop-overlay.active {
  opacity: 1 !important;
  pointer-events: auto !important;
  visibility: visible !important;
  display: block !important;
}

#backdrop-overlay.hidden {
  display: none !important;
  opacity: 0 !important;
  pointer-events: none !important;
}


/* ===== assets/css/ttsc.chat-widget.css ===== */
/* \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 
   ttsc.chat-widget.css \2014  Floating Chat Widget
   Supabase-style, uses CSS custom properties from ttsc.css
   \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550 \2550  */

/* \2500 \2500 \2500  Launcher Button \2500 \2500 \2500  */
#ttsc-chat-launcher {
    position: fixed;
    bottom: 24px;
    right: 24px;
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: var(--accent, #3b82f6);
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.2);
    z-index: 49;
    transition: transform 0.2s, opacity 0.2s;
    border: none;
    outline: none;
}
#ttsc-chat-launcher:hover {
    transform: scale(1.08);
}
#ttsc-chat-launcher.is-hidden {
    opacity: 0;
    pointer-events: none;
}

/* \2500 \2500 \2500  Panel \2500 \2500 \2500  */
#ttsc-chat-panel {
    position: fixed;
    bottom: 0;
    right: -400px;
    width: 380px;
    max-width: 100vw;
    height: 560px;
    max-height: 100vh;
    background: var(--surface, #fff);
    border-radius: 16px 16px 0 0;
    box-shadow: none;
    z-index: 999999;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    transition: right 0.3s ease, box-shadow 0.3s ease;
    font-family: inherit;
    font-size: 13px;
}
#ttsc-chat-panel.is-open {
    right: 0;
    box-shadow: -4px 0 32px rgba(0, 0, 0, 0.15);
}

/* \2500 \2500 \2500  Panel Header \2500 \2500 \2500  */
#ttsc-chat-panel .ttsc-chat-header {
    padding: 16px;
    background: var(--accent, #3b82f6);
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-shrink: 0;
}
#ttsc-chat-panel .ttsc-chat-header .ch-avatar {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.2);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}
#ttsc-chat-panel .ttsc-chat-header .ch-info {
    display: flex;
    flex-direction: column;
}
#ttsc-chat-panel .ttsc-chat-header .ch-info .ch-name {
    font-weight: 700;
    font-size: 14px;
}
#ttsc-chat-panel .ttsc-chat-header .ch-info .ch-status {
    font-size: 11px;
    opacity: 0.8;
}
#ttsc-chat-panel .ttsc-chat-header .ch-close {
    background: none;
    border: none;
    color: #fff;
    cursor: pointer;
    font-size: 18px;
    padding: 4px;
    line-height: 1;
    opacity: 0.9;
    transition: opacity 0.15s;
}
#ttsc-chat-panel .ttsc-chat-header .ch-close:hover {
    opacity: 1;
}

/* \2500 \2500 \2500  Panel Body \2500 \2500 \2500  */
#ttsc-chat-body {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
    display: flex;
    flex-direction: column;
}

/* \2500 \2500 \2500  Bottom Navigation \2500 \2500 \2500  */
#ttsc-chat-nav {
    display: flex;
    border-top: 1px solid var(--border, #e2e8f0);
    flex-shrink: 0;
    background: var(--surface, #fff);
}
.ttsc-chat-tab {
    flex: 1;
    padding: 10px 4px;
    background: none;
    border: none;
    cursor: pointer;
    font-size: 11px;
    color: var(--muted, #94a3b8);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    transition: color 0.15s, border-color 0.15s;
    border-top: 2px solid transparent;
}
.ttsc-chat-tab i,
.ttsc-chat-tab svg {
    font-size: 16px;
}
.ttsc-chat-tab.is-active {
    color: var(--accent, #3b82f6);
    border-top-color: var(--accent, #3b82f6);
}

/* \2500 \2500 \2500  Home Tab \2500 \2500 \2500  */
.ttsc-chat-home-center {
    text-align: center;
    padding: 20px 0;
}
.ttsc-chat-home-center .ch-icon-circle {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    background: color-mix(in oklab, var(--accent, #3b82f6) 12%, transparent);
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 12px;
}
.ttsc-chat-home-center .ch-icon-circle i {
    font-size: 24px;
    color: var(--accent, #3b82f6);
}
.ttsc-chat-home-center h3 {
    font-size: 16px;
    font-weight: 700;
    margin: 0 0 4px;
    color: var(--text, #111827);
}
.ttsc-chat-home-center p {
    font-size: 12px;
    color: var(--muted, #94a3b8);
    margin: 0 0 16px;
}

.ttsc-chat-response-badge {
    padding: 8px 12px;
    background: color-mix(in oklab, #22c55e 8%, transparent);
    border-radius: 8px;
    font-size: 11px;
    color: #22c55e;
    margin-bottom: 16px;
    text-align: center;
}

#ttsc-chat-start {
    width: 100%;
    padding: 14px;
    background: var(--accent, #3b82f6);
    color: #fff;
    border: none;
    border-radius: 10px;
    cursor: pointer;
    font-size: 14px;
    font-weight: 600;
    margin-bottom: 16px;
    transition: opacity 0.15s;
}
#ttsc-chat-start:hover {
    opacity: 0.9;
}

.ttsc-chat-suggestion-label {
    font-size: 11px;
    font-weight: 600;
    color: var(--muted, #94a3b8);
    text-transform: uppercase;
    margin-bottom: 8px;
}

.ttsc-chat-sugg {
    display: block;
    width: 100%;
    text-align: left;
    padding: 10px 12px;
    margin-bottom: 6px;
    background: var(--bg, #f8fafc);
    border: 1px solid var(--border, #e2e8f0);
    border-radius: 8px;
    cursor: pointer;
    font-size: 12px;
    color: var(--text, #334155);
    transition: border-color 0.15s, background 0.15s;
}
.ttsc-chat-sugg:hover {
    border-color: var(--accent, #3b82f6);
    background: color-mix(in oklab, var(--accent, #3b82f6) 4%, var(--bg, #f8fafc));
}

/* \2500 \2500 \2500  Messages / Conversations \2500 \2500 \2500  */
.ttsc-chat-empty {
    padding: 16px 0;
    text-align: center;
}
.ttsc-chat-empty .ch-empty-icon {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: color-mix(in oklab, var(--muted, #94a3b8) 12%, transparent);
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 12px;
}
.ttsc-chat-empty .ch-empty-icon i {
    font-size: 20px;
    color: var(--muted, #94a3b8);
}
.ttsc-chat-empty h3 {
    font-size: 14px;
    font-weight: 600;
    margin: 0 0 8px;
    color: var(--text, #111827);
}
.ttsc-chat-empty p {
    font-size: 12px;
    color: var(--muted, #94a3b8);
    margin: 0 0 16px;
}

#ttsc-chat-new,
.ttsc-chat-primary-btn {
    padding: 10px 20px;
    background: var(--accent, #3b82f6);
    color: #fff;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    font-size: 12px;
    font-weight: 600;
    transition: opacity 0.15s;
}
#ttsc-chat-new:hover,
.ttsc-chat-primary-btn:hover {
    opacity: 0.9;
}

/* \2500 \2500 \2500  Conversation Messages \2500 \2500 \2500  */
#ttsc-chat-msgs {
    padding: 8px 0;
    min-height: 200px;
    flex: 1;
    overflow-y: auto;
}
.ttsc-chat-bubble-row {
    display: flex;
    margin-bottom: 8px;
}
.ttsc-chat-bubble-row.is-customer {
    justify-content: flex-end;
}
.ttsc-chat-bubble-row.is-agent {
    justify-content: flex-start;
}
.ttsc-chat-bubble {
    max-width: 80%;
    padding: 8px 12px;
    border-radius: 12px;
    font-size: 12px;
    line-height: 1.4;
    word-wrap: break-word;
}
.ttsc-chat-bubble.is-customer {
    background: var(--accent, #3b82f6);
    color: #fff;
    border-bottom-right-radius: 4px;
}
.ttsc-chat-bubble.is-agent {
    background: var(--bg, #f1f5f9);
    color: var(--text, #334155);
    border-bottom-left-radius: 4px;
}
.ttsc-chat-bubble .cb-time {
    font-size: 9px;
    opacity: 0.7;
    margin-top: 2px;
    text-align: right;
}

/* \2500 \2500 \2500  Chat Input Area \2500 \2500 \2500  */
.ttsc-chat-input-area {
    display: flex;
    gap: 6px;
    padding: 8px 0;
    border-top: 1px solid var(--border, #e2e8f0);
    margin-top: 8px;
    flex-shrink: 0;
}
#ttsc-chat-input {
    flex: 1;
    font-size: 13px;
    padding: 8px 12px;
    border: 1px solid var(--border, #e2e8f0);
    border-radius: 8px;
    background: var(--surface, #fff);
    color: inherit;
    outline: none;
    transition: border-color 0.15s;
}
#ttsc-chat-input:focus {
    border-color: var(--accent, #3b82f6);
}
#ttsc-chat-send {
    padding: 8px 16px;
    background: var(--accent, #3b82f6);
    color: #fff;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    flex-shrink: 0;
    transition: opacity 0.15s;
}
#ttsc-chat-send:hover {
    opacity: 0.9;
}
#ttsc-chat-send:disabled {
    opacity: 0.5;
    cursor: default;
}

/* \2500 \2500 \2500  Help / KB Tab \2500 \2500 \2500  */
.ttsc-chat-help-section {
    padding: 16px 0;
}
.ttsc-chat-help-section h3 {
    font-size: 14px;
    font-weight: 600;
    margin: 0 0 12px;
    color: var(--text, #111827);
}
.ttsc-chat-help-search {
    position: relative;
    margin-bottom: 16px;
}
.ttsc-chat-help-search input {
    width: 100%;
    padding: 10px 12px 10px 36px;
    border: 1px solid var(--border, #e2e8f0);
    border-radius: 8px;
    font-size: 13px;
    background: var(--surface, #fff);
    color: inherit;
    outline: none;
    box-sizing: border-box;
    transition: border-color 0.15s;
}
.ttsc-chat-help-search input:focus {
    border-color: var(--accent, #3b82f6);
}
.ttsc-chat-help-search .ch-search-icon {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--muted, #94a3b8);
    font-size: 13px;
    pointer-events: none;
}
#ttsc-help-results {
    min-height: 100px;
}

/* \2500 \2500 \2500  KB Search Results \2500 \2500 \2500  */
.ttsc-chat-kb-item {
    padding: 12px;
    border: 1px solid var(--border, #e2e8f0);
    border-radius: 8px;
    margin-bottom: 8px;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s;
}
.ttsc-chat-kb-item:hover {
    background: var(--bg, #f8fafc);
    border-color: var(--accent, #3b82f6);
}
.ttsc-chat-kb-item .kbi-title {
    font-weight: 600;
    font-size: 13px;
    margin-bottom: 4px;
    color: var(--text, #111827);
}
.ttsc-chat-kb-item .kbi-excerpt {
    font-size: 11px;
    color: var(--muted, #94a3b8);
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.ttsc-chat-open-ticket-btn {
    width: 100%;
    padding: 10px;
    background: var(--accent, #3b82f6);
    color: #fff;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    font-size: 12px;
    font-weight: 600;
    margin-top: 8px;
    transition: opacity 0.15s;
}
.ttsc-chat-open-ticket-btn:hover {
    opacity: 0.9;
}

/* \2500 \2500 \2500  Help Text \2500 \2500 \2500  */
.ttsc-chat-help-text {
    font-size: 12px;
    color: var(--muted, #94a3b8);
    text-align: center;
    padding: 20px;
}

/* \2500 \2500 \2500  Loading / Searching \2500 \2500 \2500  */
.ttsc-chat-searching {
    font-size: 12px;
    color: var(--muted, #94a3b8);
    text-align: center;
    padding: 20px;
}

/* \2500 \2500 \2500  Responsive \2500 \2500 \2500  */
@media (max-width: 480px) {
    #ttsc-chat-panel {
        width: 100vw;
        height: 100vh;
        max-height: 100vh;
        border-radius: 0;
        right: -100vw;
    }
    #ttsc-chat-panel.is-open {
        right: 0;
    }
    #ttsc-chat-launcher {
        bottom: 16px;
        right: 16px;
        width: 52px;
        height: 52px;
    }
}

/* ===== assets/css/ttsc.session-timeout.css ===== */
/* \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 
   TTSC Session Timeout Modal
   \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500 \2500  */

/* Backdrop overlay */
.ttsc-session-backdrop {
    position: fixed;
    inset: 0;
    z-index: 100000;
    background: rgba(15, 23, 42, 0.45);
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.35s ease, visibility 0.35s ease;
}

.ttsc-session-backdrop.active {
    opacity: 1;
    visibility: visible;
}

/* Modal card */
.ttsc-session-modal {
    background: #fff;
    border-radius: 16px;
    box-shadow:
        0 25px 50px -12px rgba(0, 0, 0, 0.15),
        0 0 0 1px rgba(0, 0, 0, 0.03);
    width: 100%;
    max-width: 420px;
    margin: 0 16px;
    transform: scale(0.92) translateY(12px);
    opacity: 0;
    transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1),
                opacity 0.3s ease;
    overflow: hidden;
}

.ttsc-session-backdrop.active .ttsc-session-modal {
    transform: scale(1) translateY(0);
    opacity: 1;
}

/* Header strip */
.ttsc-session-modal__header {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    padding: 24px 24px 0;
}

.ttsc-session-modal__icon {
    flex-shrink: 0;
    width: 44px;
    height: 44px;
    border-radius: 12px;
    background: #f0f4ff;
    border: 1px solid #e0e7ff;
    display: flex;
    align-items: center;
    justify-content: center;
}

.ttsc-session-modal__icon i {
    font-size: 1.15rem;
    color: #4f46e5;
}

.ttsc-session-modal__title-group {
    flex: 1;
    min-width: 0;
}

.ttsc-session-modal__title {
    font-size: 1rem;
    font-weight: 700;
    color: #1e293b;
    line-height: 1.3;
    margin: 0;
}

.ttsc-session-modal__subtitle {
    font-size: 0.8rem;
    color: #94a3b8;
    margin-top: 2px;
    line-height: 1.4;
}

.ttsc-session-modal__close {
    flex-shrink: 0;
    width: 32px;
    height: 32px;
    border-radius: 8px;
    border: none;
    background: transparent;
    color: #94a3b8;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.2s ease, color 0.2s ease;
}

.ttsc-session-modal__close:hover {
    background: #f1f5f9;
    color: #475569;
}

/* Body */
.ttsc-session-modal__body {
    padding: 20px 24px;
}

.ttsc-session-modal__message {
    font-size: 0.875rem;
    color: #475569;
    line-height: 1.6;
    margin: 0;
}

.ttsc-session-modal__message strong {
    color: #1e293b;
    font-weight: 600;
}

/* Countdown */
.ttsc-session-modal__countdown {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 24px;
    margin-bottom: 20px;
}

.ttsc-session-modal__timer {
    font-size: 0.85rem;
    font-weight: 600;
    color: #ef4444;
    display: flex;
    align-items: center;
    gap: 6px;
    animation: ttsc-pulse-soft 2s ease-in-out infinite;
}

.ttsc-session-modal__timer i {
    font-size: 0.75rem;
}

/* Progress bar */
.ttsc-session-modal__progress-track {
    flex: 1;
    height: 4px;
    background: #f1f5f9;
    border-radius: 4px;
    margin-left: 16px;
    overflow: hidden;
}

.ttsc-session-modal__progress-bar {
    height: 100%;
    background: linear-gradient(90deg, #ef4444, #f97316);
    border-radius: 4px;
    transition: width 1s linear;
    width: 100%;
}

/* Footer with actions */
.ttsc-session-modal__footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
    padding: 16px 24px;
    background: #fafbfc;
    border-top: 1px solid #f1f5f9;
}

.ttsc-session-modal__btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 9px 20px;
    border-radius: 10px;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    border: none;
    transition: all 0.2s ease;
    font-family: inherit;
    line-height: 1;
}

.ttsc-session-modal__btn i {
    font-size: 0.8rem;
}

/* Sair (secondary) */
.ttsc-session-modal__btn--logout {
    background: #fff;
    color: #475569;
    border: 1px solid #e2e8f0;
}

.ttsc-session-modal__btn--logout:hover {
    background: #f8fafc;
    border-color: #cbd5e1;
    color: #1e293b;
}

/* Continue session (primary) */
.ttsc-session-modal__btn--continue {
    background: #4f46e5;
    color: #fff;
}

.ttsc-session-modal__btn--continue:hover {
    background: #4338ca;
    box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3);
}

/* Soft pulse animation for countdown */
@keyframes ttsc-pulse-soft {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.6; }
}

/* \2500 \2500 \2500  Dark mode \2500 \2500 \2500  */
.dark .ttsc-session-modal {
    background: #1e293b;
    box-shadow:
        0 25px 50px -12px rgba(0, 0, 0, 0.5),
        0 0 0 1px rgba(255, 255, 255, 0.05);
}

.dark .ttsc-session-modal__icon {
    background: rgba(79, 70, 229, 0.12);
    border-color: rgba(79, 70, 229, 0.2);
}

.dark .ttsc-session-modal__title {
    color: #f1f5f9;
}

.dark .ttsc-session-modal__subtitle {
    color: #64748b;
}

.dark .ttsc-session-modal__close {
    color: #64748b;
}

.dark .ttsc-session-modal__close:hover {
    background: #334155;
    color: #94a3b8;
}

.dark .ttsc-session-modal__message {
    color: #94a3b8;
}

.dark .ttsc-session-modal__message strong {
    color: #e2e8f0;
}

.dark .ttsc-session-modal__progress-track {
    background: #334155;
}

.dark .ttsc-session-modal__footer {
    background: #172032;
    border-top-color: #334155;
}

.dark .ttsc-session-modal__btn--logout {
    background: #334155;
    color: #cbd5e1;
    border-color: #475569;
}

.dark .ttsc-session-modal__btn--logout:hover {
