/* ===== assets/css/ttsc.pii-reveal.css ===== */
/* =========================================================
   ttsc.pii-reveal.css
   Estilos para o componente <span class="pii-cell"> gerado
   pelo helper pii_cell() do Helpers.php.
   ========================================================= */

.pii-cell {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-family: var(--font-mono, monospace);
    font-size: 12px;
    color: var(--muted);
    padding: 2px 4px 2px 8px;
    border-radius: 6px;
    background: color-mix(in oklab, var(--accent) 6%, transparent);
    border: 1px solid color-mix(in oklab, var(--accent) 12%, transparent);
    max-width: 100%;
    vertical-align: middle;
    transition: all 150ms ease;
}

.pii-cell:hover {
    border-color: color-mix(in oklab, var(--accent) 30%, transparent);
    background: color-mix(in oklab, var(--accent) 12%, transparent);
}

.pii-cell__value {
    font-family: var(--font-mono, monospace);
    font-size: 12px;
    color: var(--fg-2);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 240px;
}

.pii-cell[style*="display: block"] .pii-cell__value {
    max-width: 100%;
    white-space: normal;
}

.pii-cell__reveal {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    border: none;
    background: transparent;
    color: var(--muted);
    cursor: pointer;
    border-radius: 4px;
    transition: all 150ms ease;
    flex-shrink: 0;
    padding: 0;
}

.pii-cell__reveal:hover {
    background: color-mix(in oklab, var(--accent) 18%, transparent);
    color: var(--accent);
}

.pii-cell__reveal:active {
    transform: scale(0.92);
}

.pii-cell__reveal.is-loading {
    pointer-events: none;
    opacity: 0.5;
}

.pii-cell__reveal.is-loading::after {
    content: "";
    width: 10px;
    height: 10px;
    border: 1.5px solid currentColor;
    border-right-color: transparent;
    border-radius: 50%;
    animation: pii-spinner 0.8s linear infinite;
    margin-left: 2px;
}

@keyframes pii-spinner {
    to { transform: rotate(360deg); }
}

.pii-cell[data-pii-revealed="1"] {
    background: color-mix(in oklab, var(--success, #16a34a) 10%, transparent);
    border-color: color-mix(in oklab, var(--success, #16a34a) 22%, transparent);
}

.pii-cell[data-pii-revealed="1"] .pii-cell__value {
    color: var(--fg);
    font-weight: 600;
}

.pii-empty {
    color: var(--muted);
    opacity: 0.6;
}

/* Reveal modal */
.pii-reveal-modal {
    display: none;
}

.pii-reveal-modal.is-open {
    display: flex;
}

