  --sc-surface: #0f172a;
  --sc-surface-2: #1e293b;
  --sc-surface-3: #1e293b;
  --sc-border: #334155;
  --sc-border-2: #334155;
  --sc-brand-soft: rgba(16, 185, 129, .1);
  --sc-brand-border: rgba(16, 185, 129, .35);
  --sc-brand-text: #34d399;
  --sc-brand-hover: #34d399;
  --sc-muted: #94a3b8;
  --sc-muted-2: #64748b;
  --sc-text: #f1f5f9;
  --sc-text-2: #e2e8f0;
  --sc-input: #1e293b;
  --sc-shadow-1: 0 1px 2px rgba(0, 0, 0, .35);
  --sc-shadow-2: 0 4px 12px rgba(0, 0, 0, .4);
  --sc-shadow-3: 0 12px 28px rgba(0, 0, 0, .55);
}
.skb {
  display: grid; gap: 14px; min-width: 0;
