/* Cabe\e7 alho do board */
.skb-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; padding: 16px 20px; background: var(--sc-surface); border: 1px solid var(--sc-border); border-radius: var(--sc-r-xl); box-shadow: var(--sc-shadow-2); }
