.skb-head-main > div { min-width: 0; }
.skb-tile { width: 40px; height: 40px; border-radius: var(--sc-r-lg); background: var(--sc-brand-soft); border: 1px solid var(--sc-brand-border); color: var(--sc-brand-hover); display: inline-flex; align-items: center; justify-content: center; font-size: 15px; flex: none; }
