/* Board */
.skb-board { display: flex; align-items: flex-start; gap: 14px; overflow-x: auto; padding: 2px 2px 14px; scroll-snap-type: x proximity; -webkit-overflow-scrolling: touch; scrollbar-width: thin; }
.skb-col { --c: #64748b; flex: none; width: min(330px, 86vw); min-width: 0; scroll-snap-align: start; display: flex; flex-direction: column; gap: 10px; padding: 14px; background: color-mix(in srgb, var(--sc-surface-2) 70%, transparent); border: 1px solid var(--sc-border); border-radius: 20px; transition: width .25s var(--sc-ease), padding .25s var(--sc-ease); position: relative; }
