.skb-col-head { display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; grid-template-areas: "dot title count btn" ". sum sum sum"; align-items: center; column-gap: 8px; row-gap: 4px; padding-bottom: 10px; border-bottom: 1px solid var(--sc-border); min-width: 0; }
