.skb-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--c); }
.skb-col-title { font-size: 12px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--sc-text-2); min-width: 0; line-height: 1.25; overflow-wrap: anywhere; }
.skb-count { min-width: 24px; height: 24px; padding: 0 8px; border-radius: 99px; border: 1px solid var(--sc-border); background: var(--sc-surface); font-size: 11px; font-weight: 600; display: inline-flex; align-items: center; justify-content: center; color: var(--sc-text-2); font-variant-numeric: tabular-nums; }
.skb-sum { font: 500 11px var(--sc-mono); color: var(--sc-muted); white-space: nowrap; max-width: 100%; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }

/* Bot\e3 o recolher/expandir v2.2 \2014  chevron CSS, canto direito do cabe\e7 alho */
.skb-collapse {
  width: 28px; height: 28px; padding: 0; flex: none;
