  background: var(--sc-surface); color: var(--sc-muted); box-shadow: var(--sc-shadow-1);
  cursor: pointer;
  transition: background .15s, border-color .15s, color .15s, transform .15s, box-shadow .15s;
}
.skb-collapse::before {
  content: ""; width: 7px; height: 7px;
  border-left: 2px solid currentColor; border-bottom: 2px solid currentColor; border-radius: 1px;
  transform: translateX(1.5px) rotate(45deg);
  transition: transform .2s var(--sc-ease);
}
