.skb-list.is-loading { opacity: .5; pointer-events: none; }
.skb-card { background: var(--sc-surface); border: 1px solid var(--sc-border); border-radius: 14px; padding: 12px; box-shadow: var(--sc-shadow-1); display: grid; gap: 8px; cursor: grab; touch-action: pan-y; transition: border-color .15s, box-shadow .15s; min-width: 0; overflow: hidden; }
.skb-card:hover, .skb-card:focus-visible { border-color: #34d399; box-shadow: var(--sc-shadow-2); }
.skb-card.is-dragging { opacity: .35; }
.skb-card-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.skb-code { font: 500 10px var(--sc-mono); padding: 2px 8px; border-radius: 6px; background: var(--sc-surface-2); border: 1px solid var(--sc-border); color: var(--sc-text-2); text-transform: uppercase; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 75%; }
.skb-prob { font-size: 11px; color: var(--sc-text-2); flex: none; }
.skb-title { font-size: 12px; font-weight: 700; color: var(--sc-text); line-height: 1.35; overflow-wrap: anywhere; }
.skb-org { font-size: 11px; color: var(--sc-muted); display: flex; align-items: flex-start; gap: 6px; min-width: 0; overflow-wrap: anywhere; }
.skb-card-foot { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 4px 8px; padding-top: 8px; border-top: 1px solid var(--sc-border-2); }
.skb-val { font: 700 12px var(--sc-mono); color: var(--sc-text); overflow-wrap: anywhere; }
.skb-date { font: 10px var(--sc-mono); color: var(--sc-muted-2); }
.skb-empty { text-align: center; padding: 18px 8px; font-size: 12px; color: var(--sc-muted-2); border: 1px dashed var(--sc-border); border-radius: 14px; overflow-wrap: anywhere; }

/* Adicionar item */
.skb-add { display: flex; align-items: center; justify-content: center; gap: 6px; width: 100%; padding: 9px 12px; border: 1px dashed var(--sc-border); border-radius: 12px; background: transparent; color: var(--sc-muted); font: 600 12px var(--sc-font); cursor: pointer; min-height: 38px; transition: all .15s; }
.skb-add:hover { color: var(--sc-brand-text); border-color: var(--sc-brand); background: var(--sc-brand-soft); }
.skb-form { display: grid; gap: 8px; padding: 10px; background: var(--sc-surface); border: 1px solid var(--sc-brand-border); border-radius: 14px; box-shadow: var(--sc-shadow-2); }
.skb-form input { width: 100%; padding: 7px 10px; border: 1px solid var(--sc-border); border-radius: 10px; background: var(--sc-input); color: var(--sc-text); font: 12px var(--sc-font); min-height: 34px; }
@media (max-width: 639px) { .skb-form input { font-size: 16px; } }
.skb-form input:focus { border-color: var(--sc-brand); outline: 2px solid rgba(16, 185, 129, .3); }
.skb-form-row { display: flex; gap: 8px; }
.skb-btn { padding: 7px 12px; border-radius: 10px; border: 1px solid var(--sc-border); background: var(--sc-surface); color: var(--sc-text-2); font: 600 12px var(--sc-font); cursor: pointer; min-height: 32px; }
.skb-btn:hover { border-color: #6ee7b7; color: var(--sc-brand-text); }
.skb-btn.is-primary { background: var(--sc-brand); border-color: var(--sc-brand); color: #fff; }
.skb-btn.is-primary:hover { background: var(--sc-brand-hover); color: #fff; }
.skb-btn.is-grow { flex: 1; }

/* Pagina\e7 \e3 o da coluna */
.skb-pager { display: flex; align-items: center; justify-content: space-between; gap: 6px 8px; padding-top: 8px; border-top: 1px solid var(--sc-border); flex-wrap: wrap; }
.skb-pager .grp { display: flex; align-items: center; gap: 4px; flex-wrap: wrap; }
.skb-pager button { width: 26px; height: 26px; border-radius: 8px; border: 1px solid var(--sc-border); background: var(--sc-surface); color: var(--sc-muted); cursor: pointer; font-size: 12px; padding: 0; }
.skb-pager button:hover:not(:disabled) { color: var(--sc-brand-hover); border-color: #6ee7b7; }
.skb-pager button:disabled { opacity: .4; cursor: not-allowed; }
.skb-pager input, .skb-pager select { height: 26px; border-radius: 8px; border: 1px solid var(--sc-border); background: var(--sc-surface); color: var(--sc-text-2); font: 11px var(--sc-mono); text-align: center; padding: 0 4px; }
.skb-pager input { width: 50px; }
.skb-pager select { width: auto; max-width: 100%; font-family: var(--sc-font); }
.skb-pager span { font-size: 11px; color: var(--sc-muted); white-space: nowrap; }

/* Coluna recolhida (vertical) */
.skb-col.is-collapsed { width: 56px; padding: 12px 8px; align-items: center; gap: 12px; }
.skb-col.is-collapsed .skb-tools, .skb-col.is-collapsed .skb-list, .skb-col.is-collapsed [data-addbox], .skb-col.is-collapsed .skb-pager, .skb-col.is-collapsed .skb-sum, .skb-col.is-collapsed .skb-dot { display: none; }
.skb-col.is-collapsed .skb-col-head { display: flex; flex-direction: column; grid-template-areas: none; border-bottom: 0; padding-bottom: 0; gap: 12px; width: 100%; align-items: center; }
.skb-col.is-collapsed .skb-col-title { writing-mode: vertical-rl; transform: rotate(180deg); white-space: nowrap; max-height: 230px; overflow: hidden; text-overflow: ellipsis; overflow-wrap: normal; }
.skb-col.is-collapsed::after { content: attr(data-sum); writing-mode: vertical-rl; transform: rotate(180deg); font: 500 10px var(--sc-mono); color: var(--sc-muted-2); white-space: nowrap; max-height: 150px; overflow: hidden; }
.skb-col.is-collapsed::before { content: ""; width: 4px; height: 28px; border-radius: 99px; background: var(--c); order: 5; }

/* Nova etapa */
.skb-addcol { flex: none; width: min(330px, 86vw); scroll-snap-align: start; }
.skb-addcol > .skb-add { min-height: 54px; border-radius: 20px; background: color-mix(in srgb, var(--sc-surface-2) 50%, transparent); }
.skb-newcol { display: grid; gap: 10px; padding: 14px; background: var(--sc-surface); border: 1px solid var(--sc-brand-border); border-radius: 20px; box-shadow: var(--sc-shadow-2); }
.skb-tones { display: flex; gap: 8px; flex-wrap: wrap; }
.skb-tone { width: 24px; height: 24px; border-radius: 50%; border: 2px solid var(--sc-surface); background: var(--c); cursor: pointer; padding: 0; box-shadow: 0 0 0 1px var(--sc-border); }
.skb-tone[aria-checked="true"] { box-shadow: 0 0 0 2px var(--sc-brand); }
.skb-ghost { position: fixed; z-index: 120; pointer-events: none; opacity: .92; box-shadow: var(--sc-shadow-3); transform: rotate(1.5deg); }

/* ==========================================================================
   v2.3 \2014  ADITIVO: reordenar colunas por drag do cabecalho
   ========================================================================== */
/* O board vira container de referencia do indicador de insercao (.skb-coldrop). */
.skb-board { position: relative; }
/* Cabecalho da coluna = alca de arraste (filhos interativos, como o botao de
   recolher, mantem cursor proprio e nao iniciam drag). Affordance apenas
   visual (cursor grab), sem hints textuais. */
.skb.is-reorderable .skb-col-head { cursor: grab; touch-action: pan-y; }
.skb.is-reorderable .skb-col-head:active { cursor: grabbing; }
.skb-col.is-col-dragging { opacity: .5; }
/* Ghost compacto: pill com ponto, titulo e contagem \2014  nao clona a coluna. */
.skb-ghost-col { display: inline-flex; align-items: center; gap: 8px; padding: 7px 14px; border-radius: 99px; background: var(--sc-surface); border: 1px solid var(--sc-border); font: 600 12px var(--sc-font); color: var(--sc-text); white-space: nowrap; }
.skb-ghost-col i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); flex: none; }
.skb-ghost-col em { font-style: normal; font-size: 11px; color: var(--sc-muted); }
/* Indicador de insercao: barra de 3px centrada no gap de 14px entre colunas. */
.skb-coldrop { position: absolute; width: 3px; border-radius: 99px; background: var(--sc-brand); box-shadow: 0 0 0 3px rgba(16, 185, 129, .18); pointer-events: none; z-index: 4; }

/* ==========================================================================
   v2.3 \2014  ADITIVO: overflow dos chips de etapas (botao "+N" + menu)
   ========================================================================== */
/* A faixa de etapas ancora o menu dropdown. */
.skb-stages { position: relative; }
/* Botao "+N": mesmo corpo de chip, porem neutro (nao compete com o "All stages",
   que continua pinado no fim da linha \2014  e acao, nao etapa). */
.skb-chip.is-more { background: var(--sc-surface-3); color: var(--sc-muted); font-weight: 700; font-variant-numeric: tabular-nums; }
.skb-chip.is-more:hover, .skb-chip.is-more[aria-expanded="true"] { border-color: #6ee7b7; color: var(--sc-text-2); }
.skb-chip.is-more:focus-visible { outline: 2px solid var(--sc-brand); outline-offset: 2px; }
/* Menu: mesmo markup .skb-chip (dot --c, titulo, count em) em coluna; tokens
   existentes, dark mode automatico via html.dark. */
.skb-chips-menu { position: absolute; top: calc(100% + 6px); right: 0; z-index: 80; display: flex; flex-direction: column; gap: 6px; padding: 10px; min-width: 200px; max-width: min(320px, 86vw); max-height: 320px; overflow-y: auto; background: var(--sc-surface); border: 1px solid var(--sc-border); border-radius: var(--sc-r-lg); box-shadow: var(--sc-shadow-2); }
.skb-chips-menu .skb-chip { width: 100%; justify-content: flex-start; }
.skb-chips-menu .skb-chip em { margin-left: auto; }

/* ===== assets/css/ttsc.analytics-panels.css ===== */
/* Commercial chart composition, shared by the three developer portals. */
.ttsc-analytics-grid { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;container-type:inline-size; }
.ttsc-analytics-card { min-width:0;background:var(--ttsc-surface,#fff);border:1px solid var(--ttsc-border,#e2e8f0);border-radius:16px;padding:20px;box-shadow:0 1px 3px #0f172a0c;font-family:var(--ttsc-font-sans,Inter,sans-serif); }
.ttsc-analytics-card.is-wide {grid-column:1/-1;}
.ttsc-analytics-head {display:flex;justify-content:space-between;align-items:flex-start;gap:12px;border-bottom:1px solid #edf2f7;padding-bottom:12px;margin-bottom:18px;}
.ttsc-analytics-head h3 {margin:0;color:var(--ttsc-text,#0f172a);font-size:13px;font-weight:700;line-height:1.5;}
.ttsc-analytics-head h3 i {color:#059669;margin-right:8px;font-size:12px;}
.ttsc-analytics-head p {font-size:11px;line-height:1.6;color:#64748b;margin:3px 0 0;}
.ttsc-analytics-action {display:inline-flex;align-items:center;justify-content:center;gap:6px;flex-shrink:0;border:1px solid #dbe5ef;border-radius:10px;padding:7px 10px;background:var(--ttsc-surface,#fff);color:#475569;font:600 11px/16px var(--ttsc-font-sans,Inter,sans-serif);cursor:pointer;}
.ttsc-analytics-action:hover {border-color:#6ee7b7;color:#047857;background:#ecfdf5;}
.ttsc-analytics-action:focus-visible {outline:2px solid #10b981;outline-offset:2px;}
.ttsc-analytics-badges {display:flex;flex-wrap:wrap;gap:6px;align-items:center;min-height:26px;margin-bottom:12px;}
.ttsc-analytics-badge {padding:4px 8px;border:1px solid #dbe5ef;border-radius:8px;color:#475569;font-size:10px;line-height:14px;background:#f8fafc;}
.ttsc-analytics-badge:first-child {background:#ecfdf5;border-color:#a7f3d0;color:#047857;}
.ttsc-analytics-plot {position:relative;height:260px;min-width:0;width:100%;}
.ttsc-analytics-plot canvas {max-width:100%;}
.ttsc-analytics-foot {display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:10px;border-top:1px solid #edf2f7;margin-top:16px;padding-top:12px;color:#64748b;font-size:10px;line-height:1.6;}
.ttsc-analytics-key {display:inline-flex;align-items:center;gap:6px;margin-right:12px;}
.ttsc-analytics-key i {width:9px;height:9px;border-radius:3px;display:inline-block;}
.ttsc-analytics-empty {display:grid;place-content:center;text-align:center;gap:8px;min-height:220px;border:1px dashed #cbd5e1;border-radius:12px;background:#f8fafc;color:#64748b;font-size:12px;padding:24px;}
.ttsc-analytics-empty strong {color:#0f172a;}
.ttsc-analytics-breakdown {display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:center;}
.ttsc-analytics-breakdown .ttsc-analytics-plot {height:240px;}
.ttsc-analytics-categories {display:grid;gap:8px;max-height:250px;overflow-y:auto;}
.ttsc-analytics-category {display:flex;justify-content:space-between;align-items:center;gap:12px;border:1px solid #e2e8f0;border-radius:10px;padding:10px;font-size:11px;}
.ttsc-analytics-category span {min-width:0;overflow-wrap:anywhere;}
.ttsc-analytics-category strong {white-space:nowrap;font-size:11px;color:#0f172a;}
.ttsc-analytics-drawer {--drawer-width:min(460px,94vw);font-family:var(--ttsc-font-sans,Inter,sans-serif);}
.ttsc-analytics-drawer .drawer-head {display:flex;align-items:center;justify-content:space-between;gap:16px;flex-shrink:0;padding:20px;border-bottom:1px solid #e2e8f0;}
.ttsc-analytics-drawer h3 {font-size:15px;font-weight:700;color:var(--ttsc-text,#0f172a);margin:0;}
.ttsc-analytics-drawer .drawer-head p {font-size:11px;line-height:1.6;color:#64748b;margin-top:4px;}
.ttsc-analytics-drawer .drawer-body {overflow:auto;flex:1;padding:20px;display:flex;flex-direction:column;gap:18px;}
.ttsc-analytics-field {display:flex;flex-direction:column;gap:7px;color:#334155;font:600 12px/18px var(--ttsc-font-sans,Inter,sans-serif);}
.ttsc-analytics-field select,.ttsc-analytics-field input {width:100%;min-height:38px;border:1px solid #dbe5ef;border-radius:10px;padding:9px 12px;background:var(--ttsc-surface,#fff);color:var(--ttsc-text,#0f172a);font:400 12px/18px var(--ttsc-font-sans,Inter,sans-serif);}
.ttsc-analytics-field small {color:#64748b;font-weight:400;font-size:11px;line-height:1.5;}
.ttsc-analytics-drawer .drawer-foot {flex-shrink:0;display:flex;justify-content:space-between;gap:10px;padding:16px 20px;border-top:1px solid #e2e8f0;}
.ttsc-analytics-apply {background:#059669;color:#fff;border-color:#059669;}
.ttsc-analytics-error {font-size:12px;color:#b91c1c;}
/* Monthly Revenue Forecast \2014  model parity: CSS bars, dashed baseline, crosshair + dynamic tooltip */
.ttsc-forecast {position:relative;}
.ttsc-forecast-columns {position:relative;display:flex;gap:8px;height:240px;border-bottom:1px solid #e2e8f0;}
.ttsc-forecast-column {position:relative;flex:1 1 0;min-width:0;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;cursor:pointer;outline:none;}
.ttsc-forecast-value {margin-bottom:4px;font:700 10px/1.2 var(--ttsc-font-mono,monospace);color:#334155;opacity:0;transition:opacity .15s ease;pointer-events:none;white-space:nowrap;}
.ttsc-forecast-track {width:100%;border-radius:8px 8px 0 0;padding:4px;box-shadow:0 1px 2px rgba(15,23,42,.06);transition:filter .15s ease;}
.ttsc-forecast-fill {width:100%;border-radius:5px 5px 0 0;opacity:.85;transition:opacity .15s ease;}
.ttsc-forecast-month {margin-top:4px;font-size:11px;font-weight:600;line-height:1.2;color:#475569;transition:color .15s ease;}
.ttsc-forecast-column:hover .ttsc-forecast-value,.ttsc-forecast-column:focus-visible .ttsc-forecast-value {opacity:1;}
.ttsc-forecast-column:hover .ttsc-forecast-month,.ttsc-forecast-column:focus-visible .ttsc-forecast-month {color:#047857;}
.ttsc-forecast-column:hover .ttsc-forecast-track,.ttsc-forecast-column:focus-visible .ttsc-forecast-track {filter:saturate(1.45);}
.ttsc-forecast-column:hover .ttsc-forecast-fill,.ttsc-forecast-column:focus-visible .ttsc-forecast-fill {opacity:1;}
.ttsc-forecast-target {position:absolute;left:0;right:0;border-top:1px dashed #10b981;z-index:6;pointer-events:none;}
.ttsc-forecast-target-label {position:absolute;left:8px;bottom:3px;background:#fff;border:1px solid #a7f3d0;color:#047857;border-radius:4px;padding:3px 6px;font:600 10px/14px var(--ttsc-font-mono,monospace);}
.ttsc-forecast-target-total {position:absolute;right:8px;bottom:3px;background:#fff;border:1px solid #e2e8f0;color:#059669;border-radius:4px;padding:3px 6px;font:600 10px/14px var(--ttsc-font-mono,monospace);}
.ttsc-forecast-crosshair {position:absolute;top:0;border-left:1px dashed #10b981;z-index:7;pointer-events:none;}
.ttsc-forecast-crosshair-dot {position:absolute;bottom:-4px;left:-4px;width:8px;height:8px;border-radius:50%;background:#34d399;border:2px solid #fff;box-shadow:0 1px 2px rgba(15,23,42,.15);}
.ttsc-forecast-tip {position:absolute;top:0;z-index:10;width:200px;padding:10px;border-radius:12px;background:#1e232a;border:1px solid #334155;color:#e2e8f0;box-shadow:0 18px 30px rgba(15,23,42,.3);pointer-events:none;font-size:10px;}
.ttsc-forecast-tip-head {display:flex;align-items:center;justify-content:space-between;gap:8px;padding-bottom:5px;margin-bottom:6px;border-bottom:1px solid rgba(51,65,85,.8);}
.ttsc-forecast-tip-head strong {font-size:10px;color:#e2e8f0;}
.ttsc-forecast-tip-badge {font:700 9px var(--ttsc-font-mono,monospace);color:#34d399;background:rgba(6,78,59,.6);border:1px solid rgba(16,185,129,.3);padding:1px 4px;border-radius:4px;white-space:nowrap;}
.ttsc-forecast-tip-body {display:grid;gap:4px;font-family:var(--ttsc-font-mono,monospace);font-size:10px;}
.ttsc-forecast-tip-body > div {display:flex;justify-content:space-between;gap:8px;}
.ttsc-forecast-tip-body span {color:#94a3b8;font-family:var(--ttsc-font-sans,Inter,sans-serif);}
.ttsc-forecast-tip-body b {color:#e2e8f0;font-weight:700;white-space:nowrap;}
.ttsc-forecast-tip-body b.is-real,.ttsc-forecast-tip-body b.is-up {color:#34d399;}
.ttsc-forecast-tip-body b.is-down {color:#fb7185;}
.ttsc-forecast-tip-arrow {position:absolute;bottom:-6px;width:0;height:0;border-left:6px solid transparent;border-right:6px solid transparent;border-top:6px solid #1e232a;}
.ttsc-forecast-tip[hidden],.ttsc-forecast-crosshair[hidden],.ttsc-forecast-tip-badge[hidden] {display:none;}
/* Model-style dark tooltip shared by the Chart.js panels (bar, line, doughnut) */
.ttsc-chart-tip {position:absolute;z-index:20;min-width:180px;max-width:280px;padding:10px 12px;border-radius:12px;background:#1e232a;border:1px solid #334155;color:#e2e8f0;box-shadow:0 18px 30px rgba(15,23,42,.3);pointer-events:none;font-size:10px;opacity:0;visibility:hidden;transition:opacity .12s ease;}
.ttsc-chart-tip-head {display:flex;align-items:center;gap:8px;padding-bottom:6px;margin-bottom:6px;border-bottom:1px solid rgba(51,65,85,.8);font-weight:700;font-size:10px;min-width:0;}
.ttsc-chart-tip-head i {width:8px;height:8px;border-radius:50%;display:inline-block;flex-shrink:0;}
.ttsc-chart-tip-head strong {font-size:10px;color:#e2e8f0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.ttsc-chart-tip-head span {margin-left:auto;font-family:var(--ttsc-font-mono,monospace);font-weight:700;font-size:10px;white-space:nowrap;}
.ttsc-chart-tip-body {display:grid;gap:5px;font-family:var(--ttsc-font-mono,monospace);font-size:10px;}
.ttsc-chart-tip-body > div {display:flex;align-items:center;gap:8px;}
.ttsc-chart-tip-body i {width:8px;height:8px;border-radius:2px;display:inline-block;flex-shrink:0;}
.ttsc-chart-tip-body span {color:#94a3b8;font-family:var(--ttsc-font-sans,Inter,sans-serif);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.ttsc-chart-tip-body b {margin-left:auto;color:#f1f5f9;font-weight:700;white-space:nowrap;}
.ttsc-chart-tip-arrow {position:absolute;top:50%;width:0;height:0;border-top:6px solid transparent;border-bottom:6px solid transparent;margin-top:-6px;}
.ttsc-chart-tip-arrow.is-right {left:-6px;border-right:6px solid #1e232a;}
.ttsc-chart-tip-arrow.is-left {right:-6px;border-left:6px solid #1e232a;}
@media(min-width:1700px){.ttsc-analytics-grid.has-three-columns{grid-template-columns:repeat(3,minmax(0,1fr));}}
