/* ===== assets/css/ttsc.developer-dashboard.css ===== */
/* Route-scoped refinements for the Developer dashboard. Shared tokens and
   commercial model primitives remain the source for colors and typography. */
body.developer-dashboard #main-viewport,
body.developer-dashboard .developer-dashboard-content,
body.developer-dashboard .dashboard-panel {
  min-width: 0;
  max-width: 100%;
}

body.developer-dashboard .developer-dashboard-content {
  display: flex;
  flex-direction: column;
  gap: var(--ttsc-page-gap, 0.875rem);
  container-name: developer-dashboard;
  container-type: inline-size;
}

body.developer-dashboard #dashboard-tab-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
